(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,61627,35045,a=>{"use strict";let n=[{id:"addressing",icon:"🙇",title:{en:"Addressing people & 您",id:"Menyapa orang & 您"},body:{en:"Chinese address is built on title and relationship far more than on first names. Strangers, elders, teachers, and superiors are addressed with Surname + Title — 王老师 (Teacher Wang), 李经理 (Manager Li), 张医生 (Doctor Zhang) — rather than a given name. Using someone's bare given name signals real closeness, so it's best reserved for people who have already invited that familiarity.\n\n您 (nín) is the polite/formal 'you', used for elders, first-time contacts, customers, and anyone clearly senior to you — it's especially common in northern China and Beijing service culture. Among peers, classmates, and close friends, the plain 你 (nǐ) is normal and 您 can even feel stiff or distant. When in doubt with someone older or more senior, default to 您; you can always relax into 你 once they signal it's fine.\n\n怎么称呼您? ('How should I address you?') is the standard polite way to ask someone's name or title on first meeting, more graceful than a blunt '你叫什么名字?'. Once you know a title, use it consistently rather than switching to a given name — Chinese colleagues will often introduce themselves by surname and role specifically so you know how to address them going forward.",id:"Cara menyapa orang dalam bahasa Mandarin lebih mengandalkan gelar dan hubungan daripada nama depan. Orang asing, orang yang lebih tua, guru, dan atasan disapa dengan Marga + Gelar — 王老师 (Guru Wang), 李经理 (Manajer Li), 张医生 (Dokter Zhang) — bukan dengan nama depan. Memanggil seseorang dengan nama depan saja menandakan kedekatan yang sesungguhnya, jadi sebaiknya disimpan untuk orang yang sudah mengundang keakraban itu.\n\n您 (nín) adalah bentuk 'kamu' yang sopan/formal, dipakai untuk orang yang lebih tua, kontak pertama kali, pelanggan, dan siapa pun yang jelas lebih senior — terutama umum di Tiongkok utara dan budaya layanan di Beijing. Di antara teman sebaya, teman sekelas, dan sahabat dekat, 你 (nǐ) biasa saja dipakai, dan 您 malah bisa terasa kaku atau berjarak. Kalau ragu menghadapi orang yang lebih tua atau senior, gunakan 您 sebagai default — kamu selalu bisa beralih ke 你 begitu mereka memberi isyarat itu boleh.\n\n怎么称呼您? ('Bagaimana saya harus memanggil Anda?') adalah cara sopan standar untuk menanyakan nama atau gelar seseorang saat pertama bertemu, lebih halus daripada langsung bertanya '你叫什么名字?'. Setelah tahu gelarnya, gunakan itu secara konsisten daripada beralih ke nama depan — rekan kerja Tionghoa sering memperkenalkan diri dengan marga dan jabatan secara spesifik supaya kamu tahu cara memanggil mereka selanjutnya."},phrases:[{s:"您好",p:"nín hǎo",en:"hello (formal, respectful)",id:"halo (formal, hormat)"},{s:"你好",p:"nǐ hǎo",en:"hello (casual)",id:"halo (santai)"},{s:"请问",p:"qǐng wèn",en:"excuse me, may I ask...",id:"permisi, boleh saya bertanya..."},{s:"怎么称呼您",p:"zěn me chēng hu nín",en:"how should I address you?",id:"bagaimana saya harus memanggil Anda?"},{s:"王老师",p:"Wáng lǎo shī",en:"Teacher Wang (Surname + Title)",id:"Guru Wang (Marga + Gelar)"},{s:"李经理",p:"Lǐ jīng lǐ",en:"Manager Li",id:"Manajer Li"}],tips:[{en:"Default to 您 with anyone older, senior, or just met — switch to 你 only once invited.",id:"Gunakan 您 sebagai default untuk siapa pun yang lebih tua, senior, atau baru dikenal — beralih ke 你 hanya setelah dipersilakan."},{en:"Lead with Surname + Title (老师/经理/总/医生), never a bare given name, for new contacts.",id:"Sapa dengan Marga + Gelar (老师/经理/总/医生), jangan nama depan saja, untuk kontak baru."},{en:"Ask 怎么称呼您? rather than guessing someone's name or title.",id:"Tanyakan 怎么称呼您? daripada menebak nama atau gelar seseorang."}]},{id:"refusals",icon:"🙅",title:{en:"Polite refusals",id:"Penolakan yang sopan"},body:{en:"Directly saying 不 ('no') to an invitation, request, or offer can sound abrupt in Chinese social contexts, even when a refusal is completely reasonable. The common pattern is to soften the no with an apology, a vague reason, and often an alternative — 不好意思，这次可能不行 ('Sorry, I don't think I can this time') leaves the door open without a flat rejection.\n\nHedging phrases like 我再考虑一下 ('let me think it over') or 恐怕不太方便 ('I'm afraid that's not too convenient') function as soft no's — a direct, detailed reason usually isn't expected or required. Piling on excessive justification can actually seem suspicious; a light, vague reason plus an apologetic tone communicates the refusal clearly enough.\n\nAt meals in particular, expect a ritual of offering and refusing (推让) — a host may offer food, drink, or to pay, and the first one or two refusals are just politeness, not a real no. A genuine refusal usually needs to be repeated more firmly, ideally with a concrete reason (health, driving, an early morning), or it will be read as the expected first round of modesty rather than an actual decline.",id:"Mengatakan 不 ('tidak') secara langsung terhadap undangan, permintaan, atau tawaran bisa terdengar kasar dalam konteks sosial Tionghoa, bahkan ketika penolakan itu sepenuhnya wajar. Pola umumnya adalah melunakkan penolakan dengan permintaan maaf, alasan yang samar, dan sering kali alternatif — 不好意思，这次可能不行 ('Maaf, sepertinya kali ini saya tidak bisa') membuka jalan tanpa penolakan yang tegas.\n\nFrasa melunakkan seperti 我再考虑一下 ('biar saya pikirkan dulu') atau 恐怕不太方便 ('sepertinya kurang nyaman/pas') berfungsi sebagai penolakan halus — alasan yang rinci biasanya tidak diharapkan atau diperlukan. Memberi terlalu banyak alasan justru bisa terkesan mencurigakan; alasan ringan dan samar disertai nada minta maaf sudah cukup menyampaikan penolakan dengan jelas.\n\nTerutama saat makan, akan ada semacam ritual menawarkan dan menolak (推让) — tuan rumah mungkin menawarkan makanan, minuman, atau untuk membayar, dan satu-dua penolakan pertama hanyalah basa-basi sopan, bukan penolakan sungguhan. Penolakan yang sungguh-sungguh biasanya perlu diulang dengan lebih tegas, idealnya disertai alasan konkret (kesehatan, harus menyetir, besok pagi harus bangun awal), kalau tidak akan dianggap sebagai ronde kesopanan pertama yang wajar, bukan penolakan sebenarnya."},phrases:[{s:"不好意思，这次可能不行",p:"bù hǎo yì si, zhè cì kě néng bù xíng",en:"sorry, I don't think I can this time",id:"maaf, sepertinya kali ini saya tidak bisa"},{s:"我再考虑一下",p:"wǒ zài kǎo lǜ yí xià",en:"let me think it over",id:"biar saya pikirkan dulu"},{s:"恐怕不太方便",p:"kǒng pà bú tài fāng biàn",en:"I'm afraid that's not too convenient",id:"sepertinya kurang nyaman/pas"},{s:"改天吧",p:"gǎi tiān ba",en:"maybe another day",id:"lain kali saja ya"},{s:"心领了",p:"xīn lǐng le",en:"I appreciate the thought (declining)",id:"terima kasih niatnya (menolak halus)"},{s:"下次一定",p:"xià cì yí dìng",en:"definitely next time",id:"pasti lain kali"}],tips:[{en:"Soften a refusal with an apology + vague reason rather than a flat 不.",id:"Lunakkan penolakan dengan permintaan maaf + alasan samar, bukan 不 yang tegas."},{en:"At meals, expect to refuse food/drink/the bill once or twice before it's taken seriously.",id:"Saat makan, siapkan diri menolak makanan/minuman/tagihan sekali-dua kali sebelum dianggap serius."},{en:"Avoid over-explaining — a light reason plus 不好意思 is usually enough.",id:"Jangan terlalu banyak menjelaskan — alasan ringan plus 不好意思 biasanya sudah cukup."}]},{id:"disagreement",icon:"🤔",title:{en:"Disagreeing indirectly",id:"Tidak setuju secara tidak langsung"},body:{en:"Chinese communication is often high-context: direct contradiction, especially of someone senior or in front of a group, is avoided in favor of hedged, face-saving language. Rather than 你错了 ('you're wrong'), speakers acknowledge first — 您说得对，不过… ('you're right, but...') — before introducing a different view.\n\nVague qualifiers like 可能, 也许, or 这个问题有点复杂 ('this is a bit complicated') signal disagreement is coming without stating it bluntly. Silence, a pause, or a change of subject can also be a soft no or disagreement — worth reading as a signal rather than genuine indifference.\n\nIn meetings, strong objections to a superior's proposal are typically raised privately afterward rather than publicly during the meeting itself, to avoid making the senior person lose face in front of others. Suggesting rather than asserting — 这样是不是更好? ('wouldn't this be better?') — is a common way to offer a correction without framing it as one.",id:"Komunikasi Tionghoa sering bersifat konteks tinggi — bertentangan secara langsung, apalagi dengan orang yang lebih senior atau di depan kelompok, biasanya dihindari demi bahasa yang lebih halus dan menjaga muka. Alih-alih 你错了 ('kamu salah'), orang biasanya mengakui dulu — 您说得对，不过… ('Anda benar, tapi...') — sebelum menyampaikan pandangan yang berbeda.\n\nKata-kata pelunak seperti 可能, 也许, atau 这个问题有点复杂 ('masalah ini agak rumit') menandakan ketidaksetujuan akan datang tanpa menyatakannya secara blak-blakan. Diam, jeda, atau mengalihkan topik juga bisa berarti penolakan atau ketidaksetujuan halus — sebaiknya dibaca sebagai sinyal, bukan sekadar ketidakpedulian.\n\nDalam rapat, keberatan yang kuat terhadap usulan atasan biasanya disampaikan secara pribadi setelahnya, bukan secara terbuka saat rapat berlangsung, agar atasan tidak kehilangan muka di depan orang lain. Menyarankan alih-alih menegaskan — 这样是不是更好? ('bukankah begini lebih baik?') — adalah cara umum untuk mengoreksi tanpa terasa seperti koreksi."},phrases:[{s:"这个问题有点复杂",p:"zhè ge wèn tí yǒu diǎn fù zá",en:"this issue is a bit complicated (hedge)",id:"masalah ini agak rumit (kata pelunak)"},{s:"我有一个不同的看法",p:"wǒ yǒu yí ge bù tóng de kàn fǎ",en:"I have a different view",id:"saya punya pandangan yang berbeda"},{s:"也许我们可以再考虑一下",p:"yě xǔ wǒ men kě yǐ zài kǎo lǜ yí xià",en:"maybe we could reconsider",id:"mungkin kita bisa pertimbangkan lagi"},{s:"您说得对，不过…",p:"nín shuō de duì, bú guò...",en:"you're right, but...",id:"Anda benar, tapi..."},{s:"这样是不是更好",p:"zhè yàng shì bu shì gèng hǎo",en:"wouldn't this be better?",id:"bukankah begini lebih baik?"}],tips:[{en:"Acknowledge a point before disagreeing — 您说得对，不过… works well.",id:"Akui dulu poin lawan bicara sebelum tidak setuju — 您说得对，不过… sangat efektif."},{en:"Never say 你错了 to a superior or elder in front of others.",id:"Jangan pernah mengatakan 你错了 pada atasan atau orang yang lebih tua di depan orang lain."},{en:"Read hesitation, vague qualifiers, or silence as possible disagreement.",id:"Baca keraguan, kata pelunak, atau keheningan sebagai kemungkinan ketidaksetujuan."}]},{id:"compliments",icon:"😊",title:{en:"Responding to compliments",id:"Merespons pujian"},body:{en:"The traditional response to a compliment is to deflect rather than accept it outright — 哪里哪里 ('oh, not at all') or 过奖了 ('you flatter me') downplay the praise as a sign of modesty (谦虚), a trait valued highly in Chinese culture. Simply agreeing with a compliment can come across as arrogant to an older or more traditional listener.\n\nYounger, urban speakers increasingly respond the Western way, with a plain 谢谢夸奖 ('thanks for the compliment') or just 谢谢 — both are acceptable today, and which one lands better often depends on the listener's age and how formal the setting is. When unsure, a light deflection is the safer default, especially with elders or in a professional context.\n\nDeflecting isn't false modesty in this context — it's the expected script, and the complimenter usually understands it as polite rather than a literal denial. It's fine to follow a deflection with a small acknowledgment, e.g. 还好啦，谢谢你 ('it's just okay, but thanks'), which softens the exchange without over-claiming the praise.",id:"Respons tradisional terhadap pujian adalah mengelak, bukan menerimanya begitu saja — 哪里哪里 ('ah, tidak juga') atau 过奖了 ('Anda terlalu memuji') meredam pujian tersebut sebagai tanda kerendahan hati (谦虚), sifat yang sangat dihargai dalam budaya Tionghoa. Sekadar mengiyakan pujian bisa terkesan sombong bagi pendengar yang lebih tua atau tradisional.\n\nPenutur yang lebih muda dan tinggal di kota semakin sering merespons dengan cara ala Barat, cukup 谢谢夸奖 ('terima kasih atas pujiannya') atau sekadar 谢谢 — keduanya bisa diterima sekarang, dan mana yang lebih pas biasanya tergantung usia lawan bicara dan seberapa formal suasananya. Kalau ragu, mengelak sedikit adalah pilihan yang lebih aman, terutama dengan orang yang lebih tua atau dalam konteks profesional.\n\nMengelak di sini bukan kerendahan hati yang palsu — ini memang skrip yang diharapkan, dan orang yang memuji biasanya memahaminya sebagai kesopanan, bukan penolakan harfiah. Boleh saja melanjutkan pengelakan dengan sedikit pengakuan, misalnya 还好啦，谢谢你 ('lumayan saja, tapi terima kasih'), yang melunakkan percakapan tanpa terlalu mengklaim pujian tersebut."},phrases:[{s:"哪里哪里",p:"nǎ lǐ nǎ lǐ",en:"oh, not at all (classic modest deflection)",id:"ah, tidak juga (pengelakan sopan klasik)"},{s:"过奖了",p:"guò jiǎng le",en:"you flatter me; too kind",id:"Anda terlalu memuji"},{s:"还好啦",p:"hái hǎo la",en:"it's just okay (casual deflection)",id:"lumayan saja (pengelakan santai)"},{s:"谢谢夸奖",p:"xiè xie kuā jiǎng",en:"thanks for the compliment (modern, direct)",id:"terima kasih pujiannya (gaya modern)"},{s:"哪有",p:"nǎ yǒu",en:"not really",id:"nggak juga"}],tips:[{en:"Deflecting a compliment (哪里哪里/过奖了) is polite, not dishonest — it's the expected script.",id:"Mengelak dari pujian (哪里哪里/过奖了) itu sopan, bukan tidak jujur — itu memang skrip yang diharapkan."},{en:"With peers or in casual settings, a plain 谢谢 is increasingly fine.",id:"Dengan teman sebaya atau di suasana santai, 谢谢 saja sudah cukup pas."},{en:"Avoid enthusiastically agreeing with a compliment about yourself — it can read as boastful.",id:"Hindari mengiyakan pujian tentang dirimu dengan bersemangat — bisa terkesan sombong."}]},{id:"apologies",icon:"🙏",title:{en:"Apology levels",id:"Tingkatan permintaan maaf"},body:{en:"Chinese apologies scale by severity far more explicitly than English 'sorry' does. 不好意思 is the lightest — used constantly for minor everyday friction: bumping into someone, interrupting, asking a stranger for help, arriving a couple minutes late. It functions almost like 'excuse me' as much as 'sorry.'\n\n对不起 is a real apology for an actual fault — stepping on someone's foot rather than just brushing past them, breaking a promise, hurting someone's feelings. Using 对不起 for something trivial can feel oddly heavy, the way over-apologizing does in English. 抱歉 sits a notch more formal and is common in written apologies, customer service, and professional contexts.\n\nFor serious matters — a real mistake at work, a formal complaint, a public apology — 十分抱歉 or 非常抱歉 ('deeply/very sorry') signal genuine gravity, and 请您原谅 ('please forgive me') is reserved for asking real forgiveness. In service and business settings, an apology is usually expected to come with a concrete remedy — 我给您添麻烦了 ('I've caused you trouble') often accompanies an offer to fix the problem, not stand alone.",id:"Permintaan maaf dalam bahasa Mandarin memiliki tingkatan yang jauh lebih eksplisit dibanding kata 'sorry' dalam bahasa Inggris. 不好意思 adalah yang paling ringan — dipakai terus-menerus untuk gesekan kecil sehari-hari: menyenggol orang, memotong pembicaraan, meminta bantuan orang asing, datang terlambat beberapa menit. Fungsinya hampir seperti 'permisi' sama seperti 'maaf'.\n\n对不起 adalah permintaan maaf yang sungguhan untuk kesalahan nyata — menginjak kaki orang, bukan sekadar menyenggol, mengingkari janji, menyakiti perasaan seseorang. Memakai 对不起 untuk hal sepele bisa terasa aneh dan berlebihan, mirip seperti kalau terlalu sering minta maaf dalam bahasa Inggris. 抱歉 sedikit lebih formal dan umum dipakai dalam permintaan maaf tertulis, layanan pelanggan, dan konteks profesional.\n\nUntuk hal yang serius — kesalahan nyata di tempat kerja, keluhan resmi, permintaan maaf publik — 十分抱歉 atau 非常抱歉 ('sangat menyesal') menandakan keseriusan sesungguhnya, dan 请您原谅 ('mohon maafkan saya') dipakai khusus untuk benar-benar meminta pengampunan. Dalam konteks layanan dan bisnis, permintaan maaf biasanya diharapkan disertai solusi konkret — 我给您添麻烦了 ('saya sudah merepotkan Anda') sering menyertai tawaran untuk memperbaiki masalah, bukan berdiri sendiri."},phrases:[{s:"不好意思",p:"bù hǎo yì si",en:"excuse me; sorry (light, everyday)",id:"permisi; maaf (ringan, sehari-hari)"},{s:"对不起",p:"duì bu qǐ",en:"I'm sorry (real fault)",id:"maaf (kesalahan nyata)"},{s:"抱歉",p:"bào qiàn",en:"my apologies (more formal)",id:"mohon maaf (lebih formal)"},{s:"非常抱歉",p:"fēi cháng bào qiàn",en:"I'm very sorry (formal, serious)",id:"saya sangat menyesal (formal, serius)"},{s:"请您原谅",p:"qǐng nín yuán liàng",en:"please forgive me",id:"mohon maafkan saya"},{s:"我给您添麻烦了",p:"wǒ gěi nín tiān má fan le",en:"I've caused you trouble",id:"saya sudah merepotkan Anda"}],tips:[{en:"Use 不好意思 for everyday minor friction — it's closer to 'excuse me' than a heavy apology.",id:"Gunakan 不好意思 untuk gesekan kecil sehari-hari — lebih dekat ke 'permisi' daripada permintaan maaf berat."},{en:"Save 对不起/抱歉 for a real fault; overusing them for trivial things feels off.",id:"Simpan 对不起/抱歉 untuk kesalahan yang sungguhan; terlalu sering memakainya untuk hal sepele terasa janggal."},{en:"In service/business contexts, pair a formal apology with a concrete fix, not just words.",id:"Dalam konteks layanan/bisnis, sertai permintaan maaf formal dengan solusi konkret, bukan sekadar kata-kata."}]},{id:"restaurant",icon:"🍽️",title:{en:"Restaurant etiquette",id:"Etika di restoran"},body:{en:"At a group meal, whoever invited everyone (or the most senior person present) typically orders for the table — often asking each guest's preferences and any dietary restrictions first, then ordering family-style dishes to share. It's normal etiquette to order slightly more than the table can finish rather than too little; an empty table looks stingy, while leftovers are completely fine.\n\n请客 (treating/inviting) means whoever invited pays, and this is the strong default — offering to split the bill (AA制) with an elder, a boss, or someone hosting you for the first time can come across as refusing their hospitality. AA制 is increasingly normal among peers and younger urban friends, but it's usually the group's own custom to establish, not something a guest should propose to a host. Expect a ritual scramble for the bill (抢着买单) at the end of a meal — the real payer often insists loudly or physically takes the receipt from the server first; graciously thank them and reciprocate by hosting next time (还请) rather than truly fighting for it.\n\nToasting (敬酒) follows its own hierarchy: when clinking glasses with someone more senior or more honored than you, lower the rim of your glass slightly below theirs as a sign of respect. 干杯 means a full 'bottoms up,' while saying 随意 ('as you like') when toasting lets you sip instead, without anyone losing face. At business dinners, expect repeated toasting rounds — table hosts often go around toasting each guest individually.",id:"Dalam makan bersama, siapa pun yang mengundang (atau orang paling senior yang hadir) biasanya yang memesan untuk meja — sering kali menanyakan dulu preferensi dan pantangan makanan tiap tamu, lalu memesan hidangan gaya keluarga untuk dibagi bersama. Sudah lumrah untuk memesan sedikit lebih banyak daripada yang bisa dihabiskan meja, bukan kurang; meja yang licin tandas terkesan pelit, sementara sisa makanan sama sekali tidak masalah.\n\n请客 (mentraktir/mengundang) berarti siapa yang mengundang yang membayar, dan ini adalah kebiasaan yang sangat kuat — menawarkan untuk membagi tagihan (AA制) dengan orang yang lebih tua, atasan, atau seseorang yang pertama kali menjamu kamu bisa terkesan menolak keramahan mereka. AA制 semakin lumrah di antara teman sebaya dan anak muda perkotaan, tapi biasanya itu kebiasaan yang disepakati kelompok itu sendiri, bukan sesuatu yang diusulkan tamu kepada tuan rumah. Bersiaplah dengan ritual rebutan membayar (抢着买单) di akhir makan — orang yang benar-benar akan membayar sering kali bersikeras keras atau langsung merebut struk dari pelayan; terimalah dengan berterima kasih dan balas dengan mentraktir lain kali (还请) daripada benar-benar berebut.\n\nBersulang (敬酒) punya hierarkinya sendiri: saat mengentukkan gelas dengan orang yang lebih senior atau lebih dihormati, turunkan bibir gelasmu sedikit di bawah gelas mereka sebagai tanda hormat. 干杯 berarti menghabiskan gelas sampai tandas, sedangkan mengatakan 随意 ('sesuka hati') saat bersulang memungkinkanmu hanya menyeruput tanpa ada yang kehilangan muka. Dalam jamuan bisnis, siapkan diri untuk ronde bersulang berulang kali — tuan rumah sering berkeliling meja untuk bersulang dengan setiap tamu satu per satu."},phrases:[{s:"我请客",p:"wǒ qǐng kè",en:"it's my treat",id:"saya yang traktir"},{s:"你们先点",p:"nǐ men xiān diǎn",en:"you all order first",id:"silakan kalian pesan dulu"},{s:"我来买单",p:"wǒ lái mǎi dān",en:"let me get the bill",id:"biar saya yang bayar"},{s:"干杯",p:"gān bēi",en:"cheers! bottoms up!",id:"bersulang! habiskan!"},{s:"随意",p:"suí yì",en:"as you like (sip, no obligation to finish)",id:"sesuka hati (boleh sedikit saja)"},{s:"敬您一杯",p:"jìng nín yì bēi",en:"a toast to you (formal, to someone senior)",id:"bersulang untuk Anda (formal, ke senior)"}],tips:[{en:"Whoever invites is expected to order and pay by default — don't propose splitting with an elder or first-time host.",id:"Yang mengundang biasanya yang memesan dan membayar — jangan usulkan berbagi tagihan dengan orang yang lebih tua atau tuan rumah pertama kali."},{en:"Order a bit more food than needed rather than too little.",id:"Pesan makanan sedikit lebih banyak daripada kebutuhan, bukan kurang."},{en:"When toasting someone senior, keep your glass rim lower than theirs; say 随意 if you'd rather sip than down it.",id:"Saat bersulang dengan orang senior, jaga bibir gelasmu lebih rendah dari gelas mereka; katakan 随意 kalau ingin sekadar menyeruput."}]},{id:"gifts",icon:"🎁",title:{en:"Gift-giving taboos",id:"Pantangan memberi hadiah"},body:{en:"Several gifts are avoided because of sound or symbolism. Clocks (钟, zhōng) are the best-known taboo — 送钟 ('to gift a clock') sounds identical to 送终 ('to see someone off at their death'), so clocks and watches are avoided as gifts, especially for elders. Sharp objects like knives or scissors symbolically 'cut' a relationship; umbrellas (伞, sǎn) sound like 散 (sàn, 'to scatter/break up'), making them a poor gift between couples or close friends; and shoes (鞋, xié) can imply someone walking away from you.\n\nNumbers matter too — never give anything in a set of four, since 四 (sì) sounds like 死 (sǐ, 'death'); pears are best not shared or cut for a couple to eat together, since 梨 (lí) sounds like 离 (lí, 'to separate'). All-white flowers, chrysanthemums, and white or black wrapping are strongly associated with funerals and should be avoided for any celebratory occasion.\n\nSafe, well-liked gifts include fruit baskets, good tea, quality alcohol or cigarettes for men, and regional specialty snacks; wrap in red or gold, the auspicious colors. Present and receive gifts with both hands. It's traditional not to open a gift immediately in front of the giver — this avoids seeming greedy or making a modest gift look inadequate — though younger, casual settings are more relaxed about this. The giver may also downplay the gift ('一点小意思' — 'just a small token') before you accept; a little polite hesitation before accepting is normal and expected, not genuine reluctance.",id:"Beberapa hadiah dihindari karena bunyi atau makna simbolisnya. Jam (钟, zhōng) adalah pantangan yang paling terkenal — 送钟 ('memberi hadiah jam') bunyinya identik dengan 送终 ('mengantar seseorang di ajal kematiannya'), sehingga jam dan jam tangan dihindari sebagai hadiah, terutama untuk orang yang lebih tua. Benda tajam seperti pisau atau gunting secara simbolis 'memutus' hubungan; payung (伞, sǎn) bunyinya seperti 散 (sàn, 'berpisah/bubar'), membuatnya hadiah yang kurang cocok antara pasangan atau sahabat dekat; dan sepatu (鞋, xié) bisa berarti seseorang akan pergi meninggalkanmu.\n\nAngka juga penting — jangan pernah memberi sesuatu dalam jumlah empat, karena 四 (sì) bunyinya seperti 死 (sǐ, 'mati'); buah pir sebaiknya tidak dibagi atau dipotong untuk dimakan berdua oleh pasangan, karena 梨 (lí) bunyinya seperti 离 (lí, 'berpisah'). Bunga putih polos, bunga krisan, dan bungkusan putih atau hitam sangat identik dengan pemakaman dan sebaiknya dihindari untuk acara perayaan apa pun.\n\nHadiah yang aman dan disukai antara lain keranjang buah, teh berkualitas, minuman keras atau rokok berkualitas untuk pria, dan camilan khas daerah; bungkus dengan warna merah atau emas, warna-warna pembawa keberuntungan. Berikan dan terima hadiah dengan kedua tangan. Secara tradisi, hadiah tidak langsung dibuka di depan si pemberi — ini menghindari kesan serakah atau membuat hadiah yang sederhana terasa kurang — meski di suasana santai anak muda hal ini lebih longgar. Si pemberi mungkin juga merendahkan hadiahnya sendiri ('一点小意思' — 'ini cuma tanda kecil') sebelum kamu menerimanya; sedikit keraguan sopan sebelum menerima itu wajar dan diharapkan, bukan keengganan yang sungguhan."},phrases:[{s:"一点小意思，别客气",p:"yì diǎn xiǎo yì si, bié kè qi",en:"just a small token, don't stand on ceremony",id:"ini cuma tanda kecil, jangan sungkan"},{s:"这是送给您的",p:"zhè shì sòng gěi nín de",en:"this is for you (formal)",id:"ini untuk Anda (formal)"},{s:"太破费了",p:"tài pò fèi le",en:"you shouldn't have spent so much",id:"Anda sampai repot-repot mengeluarkan uang"},{s:"心意收到了",p:"xīn yì shōu dào le",en:"I appreciate the thought (accepting graciously)",id:"terima kasih niatnya (menerima dengan senang hati)"},{s:"谢谢，您太客气了",p:"xiè xie, nín tài kè qi le",en:"thank you, you're too kind",id:"terima kasih, Anda baik sekali"}],tips:[{en:"Never gift clocks, sharp objects, or anything in sets of four.",id:"Jangan pernah memberi hadiah jam, benda tajam, atau apa pun dalam jumlah empat."},{en:"Skip umbrellas and shared/cut pears for couples or close friends.",id:"Hindari payung serta pir yang dibagi/dipotong untuk pasangan atau sahabat dekat."},{en:"Give and receive with both hands, and wait to be told before unwrapping in front of the giver.",id:"Berikan dan terima dengan kedua tangan, dan tunggu dipersilakan sebelum membuka hadiah di depan pemberinya."}]},{id:"wechat",icon:"💬",title:{en:"WeChat etiquette",id:"Etika WeChat"},body:{en:"WeChat (微信) is the default channel for nearly everything in China — messaging, payments, official notices — so its etiquette carries real weight. Adding a new contact usually happens by scanning a QR code (扫码加我) right after meeting, sometimes replacing a business card exchange entirely in casual or younger settings.\n\n朋友圈 (Moments, WeChat's feed) functions as ongoing relationship maintenance — liking and commenting on acquaintances' posts is a small, expected gesture of goodwill, and its absence over time can be read as fading interest. Because Moments can be segmented by audience, don't assume everyone sees the same version of someone's feed. A relationship that only exists through mutual likes is sometimes called 点赞之交 ('like-only acquaintance') — a mild joke about a shallow tie.\n\nRed packets (微信红包) are a common way to say thanks, split a bill, or celebrate — including playful 拼手气红包, group packets randomly split among whoever taps fastest. In work group chats, acknowledge a boss's or group announcement with 收到 ('received') rather than staying silent, and try not to leave a voice message hanging without a reply — 已读不回 ('read but didn't reply') is a real, commonly cited social offense. Keep sensitive or political content out of group chats, and be mindful that forwarding chain messages or spam to group chats is generally unwelcome.",id:"WeChat (微信) adalah kanal utama untuk hampir segalanya di Tiongkok — mengobrol, membayar, pengumuman resmi — sehingga etikanya cukup penting. Menambah kontak baru biasanya dilakukan dengan memindai kode QR (扫码加我) langsung setelah bertemu, kadang menggantikan pertukaran kartu nama sepenuhnya di suasana santai atau anak muda.\n\n朋友圈 (Moments, linimasa WeChat) berfungsi sebagai cara menjaga hubungan — memberi like dan komentar pada unggahan kenalan adalah gestur kecil yang diharapkan sebagai tanda perhatian, dan ketiadaannya dalam waktu lama bisa dibaca sebagai berkurangnya minat. Karena Moments bisa disegmentasi berdasarkan audiens, jangan berasumsi semua orang melihat versi linimasa seseorang yang sama. Hubungan yang hanya ada lewat saling memberi like kadang disebut 点赞之交 ('kenalan sebatas like') — sindiran ringan tentang hubungan yang dangkal.\n\nAmplop merah (微信红包) adalah cara umum untuk berterima kasih, membagi tagihan, atau merayakan sesuatu — termasuk 拼手气红包 yang seru, amplop grup yang jumlahnya dibagi acak untuk siapa pun yang paling cepat membukanya. Dalam grup chat kerja, tanggapi pengumuman atasan atau grup dengan 收到 ('diterima') daripada diam saja, dan usahakan jangan membiarkan pesan suara tanpa balasan — 已读不回 ('sudah dibaca tapi tidak dibalas') adalah pelanggaran sosial nyata yang sering dikeluhkan orang. Jauhkan konten sensitif atau politik dari grup chat, dan sadari bahwa meneruskan pesan berantai atau spam ke grup umumnya tidak disukai."},phrases:[{s:"加一下微信",p:"jiā yí xià wēi xìn",en:"let's add each other on WeChat",id:"yuk tambah WeChat"},{s:"扫码加我",p:"sǎo mǎ jiā wǒ",en:"scan the code to add me",id:"pindai kode untuk menambahkan saya"},{s:"发红包",p:"fā hóng bāo",en:"send a red packet",id:"kirim amplop merah"},{s:"收到",p:"shōu dào",en:"received; got it (acknowledging a message)",id:"diterima; sudah saya baca"},{s:"已读不回",p:"yǐ dú bù huí",en:"read but didn't reply (etiquette complaint)",id:"sudah dibaca tapi tidak dibalas (keluhan etika)"},{s:"拼手气红包",p:"pīn shǒu qì hóng bāo",en:"lucky-draw red packet (randomly split in a group)",id:"amplop merah acak (dibagi acak dalam grup)"}],tips:[{en:"Reply 收到 to a boss's or group announcement rather than staying silent.",id:"Balas 收到 untuk pengumuman atasan atau grup, jangan diam saja."},{en:"Don't leave a voice message unanswered — 已读不回 is a real etiquette complaint.",id:"Jangan biarkan pesan suara tanpa balasan — 已读不回 adalah keluhan etika yang nyata."},{en:"Keep political or sensitive content out of group chats; a small red packet is a welcome way to say thanks.",id:"Jauhkan konten politik atau sensitif dari grup chat; amplop merah kecil adalah cara yang disukai untuk berterima kasih."}]},{id:"business-cards",icon:"📇",title:{en:"Business cards & first meetings",id:"Kartu nama & pertemuan pertama"},body:{en:"Business cards (名片) are exchanged with both hands, held so the text faces the recipient right-side up. Take a moment to actually read the card you receive rather than pocketing it immediately — glancing at it briefly and setting it down shows respect for the person it represents.\n\nNever write on someone's card in front of them, fold it, or put it straight in a back pocket — sitting on someone's card is considered quite rude, since the card is treated as an extension of the person's identity and face. During a meeting, place received cards neatly on the table in front of you rather than stacking them away immediately. If you're doing business in China, having cards printed with Chinese on one side is a meaningful courtesy.\n\nOffer your card to the most senior person present first, and expect a slight nod or informal bow with the exchange. First-meeting small talk often covers travel, health, and pleasantries before any business — direct questions about age or salary are common and not rude among Chinese contacts, though it's fine to answer vaguely or redirect if you'd rather not share. Punctuality is taken seriously, and seating at a first meeting is often arranged by hierarchy, with the guest of honor seated facing the door.",id:"Kartu nama (名片) diberikan dan diterima dengan kedua tangan, dipegang sehingga tulisannya menghadap si penerima dalam posisi yang bisa langsung dibaca. Luangkan waktu sejenak untuk benar-benar membaca kartu yang diterima, bukan langsung mengantonginya — melihat sekilas lalu meletakkannya dengan rapi menunjukkan rasa hormat pada orang yang diwakilinya.\n\nJangan pernah menulis di kartu seseorang di depan mereka, melipatnya, atau langsung memasukkannya ke saku belakang — duduk di atas kartu orang lain dianggap cukup tidak sopan, karena kartu itu dianggap sebagai perpanjangan identitas dan muka orang tersebut. Selama pertemuan, letakkan kartu yang diterima dengan rapi di atas meja di depanmu, bukan langsung ditumpuk dan disimpan. Kalau kamu berbisnis di Tiongkok, memiliki kartu nama yang dicetak berbahasa Mandarin di salah satu sisinya adalah bentuk sopan santun yang berarti.\n\nBerikan kartumu kepada orang paling senior yang hadir terlebih dahulu, dan siapkan diri untuk sedikit anggukan atau membungkuk ringan saat pertukaran berlangsung. Obrolan ringan saat pertemuan pertama sering membahas perjalanan, kesehatan, dan basa-basi sebelum masuk ke urusan bisnis — pertanyaan langsung soal usia atau gaji cukup umum dan tidak dianggap tidak sopan di antara kenalan Tionghoa, meski tidak masalah menjawab samar-samar atau mengalihkan topik kalau kamu tidak ingin membagikannya. Ketepatan waktu sangat diperhatikan, dan tempat duduk pada pertemuan pertama sering diatur berdasarkan hierarki, dengan tamu kehormatan didudukkan menghadap pintu."},phrases:[{s:"幸会幸会",p:"xìng huì xìng huì",en:"pleased to meet you (formal, doubled for emphasis)",id:"senang berkenalan (formal)"},{s:"请多关照",p:"qǐng duō guān zhào",en:"please look out for me; I look forward to your guidance",id:"mohon bantuannya ke depan"},{s:"这是我的名片",p:"zhè shì wǒ de míng piàn",en:"here is my business card",id:"ini kartu nama saya"},{s:"久仰久仰",p:"jiǔ yǎng jiǔ yǎng",en:"I've long admired your reputation (very formal)",id:"saya sudah lama mendengar nama Anda (sangat formal)"},{s:"以后请多指教",p:"yǐ hòu qǐng duō zhǐ jiào",en:"please guide me in the future (formal closing)",id:"mohon bimbingannya ke depannya (penutup formal)"}],tips:[{en:"Give and receive cards with both hands, and actually read the one you get before putting it away.",id:"Berikan dan terima kartu dengan kedua tangan, dan benar-benar baca kartu yang diterima sebelum menyimpannya."},{en:"Never write on, fold, or sit on someone's business card.",id:"Jangan pernah menulis di, melipat, atau menduduki kartu nama orang lain."},{en:"Offer your card to the most senior person present first.",id:"Berikan kartumu kepada orang paling senior yang hadir terlebih dahulu."}]},{id:"workplace",icon:"🏢",title:{en:"Workplace hierarchy",id:"Hierarki di tempat kerja"},body:{en:"Colleagues are addressed by Surname + Title rather than given name, especially upward: 王总 (Boss/President Wang), 李经理 (Manager Li), even 张老师 used loosely for a respected senior or skilled colleague outside of teaching. Using a superior's given name, even if you're similar in age, can come across as overly familiar or even disrespectful.\n\nRank shapes small daily behaviors: who speaks first and last in a meeting (senior figures often speak last, after hearing everyone else, or open and close the discussion), who pours tea or drinks for whom (typically the junior pours for the senior), and where people sit. Disagreement with a superior's decision is rarely voiced directly in a group setting, and is instead raised privately afterward, often introduced with 这个我们再研究一下 ('let's look into this further') as a placeholder rather than a flat no.\n\n应酬 — after-hours socializing like team dinners, drinks, or KTV with colleagues, clients, or a boss — is treated as real relationship-building, not just leisure, and can feel semi-obligatory in more traditional companies. Saying 辛苦了 ('thanks for your hard work') to a colleague after a task, a shift, or a busy stretch is a small, frequently used courtesy that costs nothing and is genuinely appreciated. Work WeChat groups often blur work and personal time, and quick replies to a boss's message — even after hours — are still expected at many companies, though this norm is increasingly contested.",id:"Rekan kerja disapa dengan Marga + Gelar, bukan nama depan, terutama ke atas: 王总 (Bos/Presdir Wang), 李经理 (Manajer Li), bahkan 张老师 dipakai secara longgar untuk senior yang dihormati atau rekan kerja yang terampil di luar konteks mengajar. Memanggil atasan dengan nama depan, meski usianya sebaya, bisa terkesan terlalu akrab atau bahkan tidak sopan.\n\nJenjang jabatan membentuk perilaku kecil sehari-hari: siapa yang bicara pertama dan terakhir dalam rapat (orang senior sering bicara terakhir, setelah mendengar semua orang, atau membuka dan menutup diskusi), siapa yang menuangkan teh atau minuman untuk siapa (biasanya yang junior menuangkan untuk yang senior), dan di mana orang duduk. Ketidaksetujuan terhadap keputusan atasan jarang disuarakan langsung dalam suasana kelompok, melainkan disampaikan secara pribadi setelahnya, sering diawali dengan 这个我们再研究一下 ('mari kita kaji lagi') sebagai penanda sementara, bukan penolakan tegas.\n\n应酬 — bersosialisasi di luar jam kerja seperti makan malam tim, minum-minum, atau karaoke (KTV) bersama rekan kerja, klien, atau atasan — dianggap sebagai membangun hubungan yang sungguhan, bukan sekadar bersantai, dan bisa terasa semi-wajib di perusahaan yang lebih tradisional. Mengucapkan 辛苦了 ('terima kasih atas kerja kerasnya') kepada rekan kerja setelah tugas, shift, atau masa sibuk adalah kesopanan kecil yang sering dipakai, tidak berbiaya apa pun, dan sungguh dihargai. Grup WeChat kerja sering mengaburkan batas waktu kerja dan pribadi, dan balasan cepat untuk pesan atasan — bahkan di luar jam kerja — masih diharapkan di banyak perusahaan, meski norma ini semakin banyak dipertanyakan."},phrases:[{s:"王总",p:"Wáng zǒng",en:"Boss/President Wang",id:"Bos/Presdir Wang"},{s:"辛苦了",p:"xīn kǔ le",en:"thanks for your hard work",id:"terima kasih atas kerja kerasnya"},{s:"我先说两句",p:"wǒ xiān shuō liǎng jù",en:"let me say a few words first",id:"biar saya bicara sedikit dulu"},{s:"请您指示",p:"qǐng nín zhǐ shì",en:"please give your guidance/instructions",id:"mohon petunjuk/arahan Anda"},{s:"这个我们再研究一下",p:"zhè ge wǒ men zài yán jiū yí xià",en:"let's look into this further (soft delay/decline)",id:"mari kita kaji lagi (penundaan/penolakan halus)"}],tips:[{en:"Address colleagues by Surname + Title, not given name, especially upward.",id:"Sapa rekan kerja dengan Marga + Gelar, bukan nama depan, terutama ke atas."},{en:"Save direct pushback on a superior's decision for a private conversation.",id:"Simpan penolakan langsung terhadap keputusan atasan untuk percakapan pribadi."},{en:"辛苦了 is a small, genuinely appreciated courtesy after someone's effort.",id:"辛苦了 adalah kesopanan kecil yang sungguh dihargai setelah usaha seseorang."}]},{id:"family-terms",icon:"👨‍👩‍👧‍👦",title:{en:"Family terms for strangers",id:"Istilah keluarga untuk orang asing"},body:{en:"Chinese kinship terms are far more specific than English — separate words distinguish paternal from maternal grandparents (爷爷/奶奶 vs 外公/外婆), older from younger siblings (哥哥/姐姐 vs 弟弟/妹妹), and each aunt or uncle by birth order and side of the family. Learning even a handful of these shows real effort and is noticed.\n\nThe pragmatic twist is that these same kinship terms are used constantly to address complete strangers, scaled to their apparent age relative to the speaker: 叔叔 (shūshu, 'uncle') for a man roughly a parent's age, 阿姨 (āyí, 'auntie') for a woman of similar age, 哥/姐 for someone a bit older than you, 爷爷/奶奶 for an elderly stranger. Children are explicitly taught to greet adults this way, and addressing an adult stranger with a bare 你 and no kinship term — especially from a child — can come across as blunt or poorly raised.\n\n师傅 (shīfu, roughly 'master/skilled worker') is a separate, genuinely useful catch-all for drivers, repair workers, and tradespeople of any age or gender, without needing to judge their exact age bracket. Getting the generational term slightly wrong (calling someone 阿姨 who feels too young for it) can occasionally cause mild offense, so lean on your honest read of someone's age rather than defaulting high or low.",id:"Istilah kekerabatan dalam bahasa Mandarin jauh lebih spesifik daripada bahasa Indonesia — ada kata terpisah untuk membedakan kakek-nenek dari pihak ayah dan ibu (爷爷/奶奶 vs 外公/外婆), kakak dari adik (哥哥/姐姐 vs 弟弟/妹妹), dan setiap paman/bibi berdasarkan urutan lahir serta pihak keluarga. Menguasai beberapa saja dari istilah ini menunjukkan usaha yang sungguhan dan akan diperhatikan orang.\n\nYang menarik secara praktis, istilah kekerabatan yang sama ini juga dipakai terus-menerus untuk menyapa orang asing, disesuaikan dengan perkiraan usia mereka relatif terhadap si penyapa: 叔叔 (shūshu, 'paman') untuk pria seusia orang tua, 阿姨 (āyí, 'bibi/tante') untuk wanita seusia serupa, 哥/姐 untuk seseorang yang sedikit lebih tua darimu, 爷爷/奶奶 untuk orang asing yang sudah lanjut usia. Anak-anak secara eksplisit diajari untuk menyapa orang dewasa dengan cara ini, dan menyapa orang dewasa asing hanya dengan 你 tanpa istilah kekerabatan — apalagi dari seorang anak — bisa terkesan kasar atau kurang diajari sopan santun.\n\n师傅 (shīfu, kira-kira 'pak/ahli') adalah sapaan serbaguna yang benar-benar berguna untuk sopir, tukang reparasi, dan pekerja terampil dari usia atau jenis kelamin apa pun, tanpa perlu menebak-nebak kisaran usia mereka secara tepat. Salah sedikit menebak istilah generasi (memanggil seseorang 阿姨 padahal ia merasa masih terlalu muda) kadang bisa sedikit menyinggung, jadi andalkan perkiraan usia yang jujur, bukan asal memilih terlalu tua atau terlalu muda."},phrases:[{s:"叔叔好",p:"shū shu hǎo",en:"hello uncle (to an adult man)",id:"halo paman"},{s:"阿姨好",p:"ā yí hǎo",en:"hello auntie (to an adult woman)",id:"halo bibi/tante"},{s:"大哥",p:"dà gē",en:"big brother (respectful, to a man a bit older)",id:"abang/kak (ke pria yang sedikit lebih tua)"},{s:"大姐",p:"dà jiě",en:"big sister (respectful, to a woman a bit older)",id:"kakak (ke wanita yang sedikit lebih tua)"},{s:"爷爷",p:"yé ye",en:"grandpa (to an elderly man)",id:"kakek (ke pria lanjut usia)"},{s:"师傅",p:"shī fu",en:"'master' (to a driver, worker, tradesperson)",id:"pak/ahli (ke sopir, pekerja, tukang)"}],tips:[{en:"Address adult strangers with a kinship term matched to their apparent age, not a bare 你.",id:"Sapa orang dewasa asing dengan istilah kekerabatan sesuai perkiraan usianya, bukan sekadar 你."},{en:"师傅 is a safe, respectful default for service workers of any age.",id:"师傅 adalah sapaan default yang aman dan sopan untuk pekerja jasa dari usia berapa pun."},{en:"Getting the term slightly wrong on someone's age is a minor slip, not a serious offense — just adjust next time.",id:"Salah menebak istilah usia seseorang hanyalah kesalahan kecil, bukan pelanggaran serius — cukup sesuaikan lain kali."}]},{id:"names",icon:"📛",title:{en:"Chinese names & address",id:"Nama Tionghoa & sapaan"},body:{en:"Chinese names put family name first and given name second — 王小明 is surname 王 (Wáng) plus given name 小明 (Xiǎomíng), the reverse of Western order. Most surnames are a single syllable, though a handful of two-syllable 'compound' surnames exist (欧阳, 司马); given names are usually one or two characters chosen for their meaning rather than picked from a fixed list.\n\nNicknames are commonly formed by doubling a character (明明) or prefixing 小 ('little') for someone younger or junior (小明), and 老 ('old') for a peer or slightly older acquaintance (老王) — the latter is familiar and respectful at once, not a comment on actual age. Using someone's bare given name alone, without the surname, is normally reserved for close friends and family; doing so with a new acquaintance can feel presumptuous.\n\nThe safest default with anyone new is Surname + Title (老师/经理/总/先生/女士) until they invite something more casual — often by introducing themselves with 可以叫我... ('you can call me...'). 请问您贵姓? ('may I ask your honorable surname?') is the standard polite script for asking someone's name. If you'll be doing business, studying, or socializing regularly in China, it's genuinely useful to have a Chinese name ready for cards, WeChat, and forms rather than improvising one on the spot.",id:"Nama Tionghoa menempatkan marga di depan dan nama diri di belakang — 王小明 adalah marga 王 (Wáng) ditambah nama diri 小明 (Xiǎomíng), kebalikan dari urutan Barat. Sebagian besar marga terdiri dari satu suku kata, meski ada beberapa marga 'gabungan' dua suku kata (欧阳, 司马); nama diri biasanya satu atau dua karakter yang dipilih karena maknanya, bukan diambil dari daftar nama baku.\n\nNama panggilan umumnya dibentuk dengan menggandakan satu karakter (明明) atau menambahkan awalan 小 ('kecil') untuk seseorang yang lebih muda atau junior (小明), dan 老 ('tua') untuk teman sebaya atau kenalan yang sedikit lebih tua (老王) — yang terakhir ini terasa akrab sekaligus sopan, bukan komentar tentang usia sesungguhnya. Memanggil seseorang dengan nama diri saja, tanpa marganya, biasanya disediakan untuk sahabat dekat dan keluarga; melakukannya pada kenalan baru bisa terkesan terlalu berani.\n\nPilihan paling aman untuk siapa pun yang baru dikenal adalah Marga + Gelar (老师/经理/总/先生/女士) sampai mereka mengundang sesuatu yang lebih santai — sering kali dengan memperkenalkan diri lewat 可以叫我... ('kamu boleh memanggilku...'). 请问您贵姓? ('boleh saya tahu marga Anda?') adalah skrip sopan standar untuk menanyakan nama seseorang. Kalau kamu akan berbisnis, belajar, atau bergaul secara rutin di Tiongkok, sungguh berguna untuk sudah punya nama Tionghoa siap pakai untuk kartu nama, WeChat, dan formulir daripada mengarang dadakan."},phrases:[{s:"请问您贵姓",p:"qǐng wèn nín guì xìng",en:"may I ask your (honorable) surname?",id:"boleh saya tahu marga Anda?"},{s:"我姓王，叫王小明",p:"wǒ xìng Wáng, jiào Wáng Xiǎo míng",en:"my surname is Wang, my name is Wang Xiaoming",id:"marga saya Wang, nama saya Wang Xiaoming"},{s:"王先生",p:"Wáng xiān sheng",en:"Mr. Wang",id:"Tuan/Bapak Wang"},{s:"王女士",p:"Wáng nǚ shì",en:"Ms. Wang",id:"Nyonya/Ibu Wang"},{s:"可以叫我小明",p:"kě yǐ jiào wǒ Xiǎo míng",en:"you can call me Xiaoming",id:"kamu boleh memanggilku Xiaoming"},{s:"老王",p:"lǎo Wáng",en:"'old Wang' (familiar nickname among peers)",id:"'Wang tua' (panggilan akrab antarteman sebaya)"}],tips:[{en:"Lead with Surname + Title for anyone new; wait to be invited before using a given name alone.",id:"Sapa dengan Marga + Gelar untuk siapa pun yang baru dikenal; tunggu diundang sebelum memakai nama diri saja."},{en:"请问您贵姓? is the polite script for asking someone's surname.",id:"请问您贵姓? adalah skrip sopan untuk menanyakan marga seseorang."},{en:"Consider having a ready Chinese name if you'll be in China regularly — it saves awkward improvising.",id:"Pertimbangkan memiliki nama Tionghoa yang siap pakai kalau kamu akan sering berada di Tiongkok — menghindari improvisasi yang canggung."}]},{id:"holidays",icon:"🧧",title:{en:"Spring Festival & holidays",id:"Imlek & hari raya"},body:{en:"春节 (Spring Festival / Lunar New Year) is the biggest holiday of the year, centered on the family reunion dinner (年夜饭) on New Year's Eve and roughly two weeks of celebration. Married or older relatives give 红包 (red envelopes of cash) to unmarried juniors and children; homes are cleaned before the new year (but not on the day itself, to avoid 'sweeping out' good luck), red decorations go up, and the world's largest annual human migration (春运) happens as people travel home.\n\n元宵节 (Lantern Festival), fifteen days after New Year, closes out the celebration with tāngyuán (glutinous rice balls) and lanterns. 清明节 (Qingming, Tomb-Sweeping Festival) in early April is for visiting and tending ancestors' graves and burning joss paper. 端午节 (Dragon Boat Festival) in early summer commemorates the poet Qu Yuan with zòngzi (sticky rice dumplings) and dragon boat races. 中秋节 (Mid-Autumn Festival) centers on family reunion, mooncakes, and viewing the full moon; 国庆节 (National Day, October 1st) is a week-long public holiday with a strong patriotic tone.\n\nEach holiday has its own expected greeting and small gift customs — 新年快乐 or 恭喜发财 at Spring Festival, mooncakes for Mid-Autumn — and most of these are also mass public holidays, so transport and tourist sites get extremely crowded around them. On New Year's Day itself, avoid sweeping, using scissors, or arguing, all traditionally considered bad luck to start the year with.",id:"春节 (Festival Musim Semi / Tahun Baru Imlek) adalah hari raya terbesar dalam setahun, berpusat pada makan malam reuni keluarga (年夜饭) di malam Tahun Baru dan sekitar dua minggu perayaan. Kerabat yang sudah menikah atau lebih tua memberi 红包 (amplop merah berisi uang) kepada yang belum menikah dan anak-anak; rumah dibersihkan sebelum tahun baru (tapi tidak pada hari-H, agar tidak 'menyapu keluar' keberuntungan), dekorasi merah dipasang, dan migrasi manusia tahunan terbesar di dunia (春运) terjadi saat orang-orang pulang kampung.\n\n元宵节 (Festival Lampion), lima belas hari setelah Tahun Baru, menutup rangkaian perayaan dengan tāngyuán (bola ketan) dan lampion. 清明节 (Qingming, Festival Ziarah Kubur) di awal April adalah waktu untuk mengunjungi dan merawat makam leluhur serta membakar kertas sembahyang. 端午节 (Festival Perahu Naga) di awal musim panas memperingati penyair Qu Yuan dengan zòngzi (ketan berbungkus daun) dan lomba perahu naga. 中秋节 (Festival Pertengahan Musim Gugur) berpusat pada reuni keluarga, kue bulan, dan menikmati bulan purnama; 国庆节 (Hari Nasional, 1 Oktober) adalah libur nasional selama seminggu dengan nuansa patriotik yang kuat.\n\nSetiap hari raya punya ucapan khas dan kebiasaan hadiah kecilnya sendiri — 新年快乐 atau 恭喜发财 saat Festival Musim Semi, kue bulan saat Pertengahan Musim Gugur — dan sebagian besar hari raya ini juga libur massal, sehingga transportasi dan tempat wisata menjadi sangat padat di sekitar tanggal tersebut. Pada hari Tahun Baru itu sendiri, hindari menyapu, membersihkan, atau memakai gunting, karena semuanya secara tradisional dianggap sial untuk mengawali tahun."},phrases:[{s:"新年快乐",p:"xīn nián kuài lè",en:"Happy New Year",id:"Selamat Tahun Baru"},{s:"恭喜发财",p:"gōng xǐ fā cái",en:"wishing you wealth and prosperity",id:"semoga makin kaya dan makmur"},{s:"红包拿来",p:"hóng bāo ná lái",en:"hand over the red envelope! (playful)",id:"amplop merahnya mana! (bercanda)"},{s:"中秋节快乐",p:"zhōng qiū jié kuài lè",en:"Happy Mid-Autumn Festival",id:"Selamat Festival Pertengahan Musim Gugur"},{s:"节日快乐",p:"jié rì kuài lè",en:"Happy Holiday (generic)",id:"Selamat Hari Raya (umum)"},{s:"过年好",p:"guò nián hǎo",en:"Happy New Year (common spoken greeting)",id:"Selamat Tahun Baru (sapaan lisan umum)"}],tips:[{en:"Give red envelopes with both hands, in even amounts (avoid 4), with clean, new-looking bills.",id:"Berikan amplop merah dengan kedua tangan, dalam jumlah genap (hindari angka 4), dengan uang kertas yang bersih dan terlihat baru."},{en:"Don't sweep, clean, or use scissors on New Year's Day.",id:"Jangan menyapu, membersihkan, atau memakai gunting pada hari Tahun Baru."},{en:"Book travel and tourist sites well ahead of Spring Festival and National Day — both see the year's heaviest crowds.",id:"Pesan transportasi dan tempat wisata jauh-jauh hari sebelum Festival Musim Semi dan Hari Nasional — keduanya adalah masa paling padat dalam setahun."}]},{id:"numbers",icon:"🔢",title:{en:"Lucky & unlucky numbers",id:"Angka mujur & sial"},body:{en:"八 (bā, eight) is the most prized number in Chinese culture because it sounds like 发 (fā, 'to prosper/get rich') — phone numbers, car plates, floor numbers, wedding dates, and prices are all chosen to include it, sometimes at a real price premium. The 2008 Beijing Olympics deliberately opened at 8:08pm on 8/8/08.\n\n四 (sì, four) is the opposite — it sounds like 死 (sǐ, 'death'), so many buildings skip a labeled 4th floor (jumping to '3A' or '5'), apartment units with a 4 are often discounted, and gifts are never given in sets of four. 六 (liù, six) is auspicious for smoothness, captured in the phrase 六六大顺 ('may everything go smoothly'), and 九 (jiǔ, nine) sounds like 久 (jiǔ, 'long-lasting'), making it a favorite for weddings and long-term wishes.\n\n二百五 (èr bǎi wǔ, '250') is a special case worth knowing: as a stand-alone insult it means roughly 'idiot' or 'fool,' rooted in old slang about currency — so using 250 casually as a price or quantity without meaning to insult anyone can land as an unintended joke or minor offense, and locals will often laugh or wince at a bill or count that lands on exactly that number.",id:"八 (bā, delapan) adalah angka paling didambakan dalam budaya Tionghoa karena bunyinya seperti 发 (fā, 'makmur/menjadi kaya') — nomor telepon, plat mobil, nomor lantai, tanggal pernikahan, dan harga sering dipilih agar mengandung angka ini, kadang dengan harga premium yang nyata. Olimpiade Beijing 2008 sengaja dibuka pukul 20:08 pada tanggal 8/8/08.\n\n四 (sì, empat) justru sebaliknya — bunyinya seperti 死 (sǐ, 'mati'), sehingga banyak gedung melewati lantai 4 (langsung ke '3A' atau '5'), unit apartemen dengan angka 4 sering didiskon, dan hadiah tidak pernah diberikan dalam jumlah empat. 六 (liù, enam) membawa keberuntungan untuk kelancaran, tercermin dalam ungkapan 六六大顺 ('semoga semuanya lancar'), dan 九 (jiǔ, sembilan) bunyinya seperti 久 (jiǔ, 'langgeng'), menjadikannya favorit untuk pernikahan dan harapan jangka panjang.\n\n二百五 (èr bǎi wǔ, '250') adalah kasus khusus yang penting diketahui: sebagai makian tersendiri artinya kira-kira 'bodoh' atau 'tolol', berakar dari bahasa gaul lama tentang mata uang — jadi memakai angka 250 secara santai sebagai harga atau jumlah tanpa maksud menghina bisa terdengar seperti lelucon tak disengaja atau sedikit menyinggung, dan orang lokal sering tertawa atau meringis kalau tagihan atau hitungan pas jatuh di angka itu."},phrases:[{s:"八",p:"bā",en:"eight (lucky — 'prosper')",id:"delapan (mujur — 'makmur')"},{s:"发财",p:"fā cái",en:"to get rich (wordplay tied to 8)",id:"menjadi kaya (permainan kata dengan angka 8)"},{s:"四",p:"sì",en:"four (avoid — sounds like 'death')",id:"empat (hindari — bunyinya seperti 'mati')"},{s:"六六大顺",p:"liù liù dà shùn",en:"may everything go smoothly (auspicious 6s)",id:"semoga semuanya lancar (angka 6 pembawa keberuntungan)"},{s:"二百五",p:"èr bǎi wǔ",en:"'250' = idiot/fool (slang insult)",id:"'250' = bodoh/tolol (makian gaul)"},{s:"九",p:"jiǔ",en:"nine (auspicious — 'long-lasting')",id:"sembilan (mujur — 'langgeng')"}],tips:[{en:"Give money or gifts in amounts with 6, 8, or 9 — avoid 4.",id:"Berikan uang atau hadiah dalam jumlah yang mengandung 6, 8, atau 9 — hindari angka 4."},{en:"Expect buildings and apartments to skip or discount the number 4.",id:"Bersiaplah menemui gedung dan apartemen yang melewati atau mendiskon angka 4."},{en:"Don't casually use '250' as a price or count — it doubles as a real insult.",id:"Jangan santai memakai angka '250' sebagai harga atau hitungan — angka itu juga berarti makian sungguhan."}]},{id:"face",icon:"🎭",title:{en:"面子 — the concept of face",id:"面子 — konsep muka"},body:{en:"面子 (miànzi) is social face — reputation, dignity, and standing in the eyes of others — and it sits near the center of nearly every Chinese social interaction. 'Giving face' (给面子) means actions that publicly honor or defer to someone: praising them in front of others, accepting their invitation, letting them win a minor point. 'Losing face' (丢脸) is the opposite, and it's most damaging when it happens publicly.\n\nIn practice, this means critical feedback is normally given privately, not in front of a group; direct public criticism of a colleague, student, or family member is avoided even when it's factually justified, because the public setting is what causes the real damage. Refusing an invitation or a gift outright, without a face-saving excuse, can cause the other person to lose face just from being refused.\n\nFace-giving works both ways and builds real social credit (人情): helping someone look good in front of their boss or family is a favor that's expected to be reciprocated later, and accepting a small favor or invitation is itself a way of giving face back to the person offering it. 死要面子 ('would rather die than lose face') describes someone who takes this to an unhealthy extreme, spending beyond their means or refusing help just to maintain appearances — a recognized cautionary idea within the culture itself, not just an outsider's critique.",id:"面子 (miànzi) adalah muka sosial — reputasi, martabat, dan posisi di mata orang lain — dan hal ini berada dekat pusat hampir setiap interaksi sosial Tionghoa. 'Memberi muka' (给面子) berarti tindakan yang secara terbuka menghormati atau mengalah pada seseorang: memuji mereka di depan orang lain, menerima undangan mereka, membiarkan mereka menang dalam hal kecil. 'Kehilangan muka' (丢脸) adalah kebalikannya, dan paling merusak ketika terjadi secara terbuka.\n\nDalam praktiknya, ini berarti kritik biasanya disampaikan secara pribadi, bukan di depan kelompok; kritik terbuka langsung terhadap rekan kerja, murid, atau anggota keluarga dihindari meski secara faktual benar, karena suasana terbuka itulah yang menyebabkan kerusakan sesungguhnya. Menolak undangan atau hadiah secara terang-terangan, tanpa alasan yang menjaga muka, bisa membuat orang lain kehilangan muka hanya karena ditolak.\n\nMemberi muka berlaku dua arah dan membangun modal sosial yang sungguhan (人情): membantu seseorang terlihat baik di depan atasan atau keluarganya adalah kebaikan yang diharapkan dibalas nanti, dan menerima kebaikan kecil atau undangan itu sendiri adalah cara memberi muka kembali kepada orang yang menawarkannya. 死要面子 ('lebih baik mati daripada kehilangan muka') menggambarkan seseorang yang membawa hal ini ke titik ekstrem yang tidak sehat, menghabiskan uang melebihi kemampuan atau menolak bantuan hanya demi menjaga penampilan — sebuah gagasan peringatan yang diakui dalam budaya itu sendiri, bukan sekadar kritik dari luar."},phrases:[{s:"给我个面子",p:"gěi wǒ ge miàn zi",en:"do me this favor (asking as a personal favor)",id:"kasih saya muka (minta tolong sebagai kebaikan pribadi)"},{s:"别让他丢脸",p:"bié ràng tā diū liǎn",en:"don't make him lose face",id:"jangan bikin dia kehilangan muka"},{s:"很有面子",p:"hěn yǒu miàn zi",en:"very prestigious; it reflects well",id:"sangat bergengsi; terlihat baik"},{s:"不给面子",p:"bù gěi miàn zi",en:"to refuse to show respect; to snub",id:"tidak menghargai; menyepelekan"},{s:"留点面子",p:"liú diǎn miàn zi",en:"leave some face; don't push too far",id:"sisakan sedikit muka; jangan kelewatan"},{s:"死要面子",p:"sǐ yào miàn zi",en:"would rather die than lose face (idiom)",id:"lebih baik mati daripada kehilangan muka (idiom)"}],tips:[{en:"Give critical feedback privately, never in front of a group.",id:"Berikan kritik secara pribadi, jangan pernah di depan kelompok."},{en:"Frame a refusal with a face-saving reason rather than a flat no.",id:"Bingkai penolakan dengan alasan yang menjaga muka, bukan penolakan tegas."},{en:"Public praise costs little and builds real goodwill — use it generously.",id:"Pujian di depan umum tidak berbiaya banyak dan membangun hubungan baik yang sungguhan — gunakan dengan murah hati."}]},{id:"taiwan-mainland",icon:"🗺️",title:{en:"Mainland vs Taiwan usage",id:"Perbedaan daratan & Taiwan"},body:{en:"The most visible difference is script: mainland China uses simplified characters (简体字), while Taiwan and Hong Kong use traditional characters (繁體字). Romanization also differs in practice — the mainland standard is Hanyu Pinyin, while Taiwan has historically taught reading with Zhuyin/Bopomofo (ㄅㄆㄇㄈ) and often spells place and personal names with older systems (Taipei, not Táiběi).\n\nVocabulary genuinely differs in ways that can cause real confusion: 土豆 means 'potato' on the mainland but often 'peanut' in Taiwan, where potato is usually 馬鈴薯 (mǎlíngshǔ); a taxi is 出租车 (chūzūchē) on the mainland but 计程车 (jìchéngchē) in Taiwan; 'video' is usually 视频 (shìpín) on the mainland versus 影片 (yǐngpiàn) as a common Taiwan term. Even shared characters can be pronounced differently — 垃圾 ('garbage') is lājī on the mainland but commonly lèsè in Taiwan.\n\nPolitics is worth flagging as a genuinely sensitive area: terms like 大陆 ('the mainland') versus 内地, or how people refer to cross-strait relations, carry real political weight, and it's wise to avoid volunteering opinions on the topic with new acquaintances from either side. If you're studying mainland Mandarin and then travel to Taiwan (or the reverse), expect some real friction in vocabulary and character recognition — it's a normal adjustment, not a sign you've learned the language wrong.",id:"Perbedaan yang paling terlihat adalah aksara: Tiongkok daratan memakai aksara sederhana (简体字), sementara Taiwan dan Hong Kong memakai aksara tradisional (繁體字). Romanisasinya juga berbeda dalam praktiknya — standar di daratan adalah Hanyu Pinyin, sementara Taiwan secara historis mengajarkan cara membaca dengan Zhuyin/Bopomofo (ㄅㄆㄇㄈ) dan sering mengeja nama tempat serta nama orang dengan sistem yang lebih lama (Taipei, bukan Táiběi).\n\nKosakata benar-benar berbeda dengan cara yang bisa membingungkan: 土豆 berarti 'kentang' di daratan tapi sering berarti 'kacang tanah' di Taiwan, di mana kentang biasanya disebut 馬鈴薯 (mǎlíngshǔ); taksi adalah 出租车 (chūzūchē) di daratan tapi 计程车 (jìchéngchē) di Taiwan; 'video' biasanya 视频 (shìpín) di daratan dibanding 影片 (yǐngpiàn) sebagai istilah umum di Taiwan. Bahkan karakter yang sama bisa dilafalkan berbeda — 垃圾 ('sampah') dibaca lājī di daratan tapi umumnya lèsè di Taiwan.\n\nPolitik patut ditandai sebagai area yang benar-benar sensitif: istilah seperti 大陆 ('daratan Tiongkok') dibanding 内地, atau bagaimana orang menyebut hubungan lintas-selat, membawa bobot politik yang nyata, dan sebaiknya hindari menyampaikan opini soal topik ini secara sukarela kepada kenalan baru dari kedua belah pihak. Kalau kamu belajar Mandarin gaya daratan lalu bepergian ke Taiwan (atau sebaliknya), siapkan diri menghadapi sedikit gesekan nyata dalam kosakata dan pengenalan karakter — ini penyesuaian yang wajar, bukan tanda kamu salah belajar bahasanya."},phrases:[{s:"土豆",p:"tǔ dòu",en:"potato (mainland) / peanut (Taiwan, dialectal)",id:"kentang (daratan) / kacang tanah (Taiwan)"},{s:"出租车",p:"chū zū chē",en:"taxi (mainland term)",id:"taksi (istilah daratan)"},{s:"计程车",p:"jì chéng chē",en:"taxi (Taiwan term)",id:"taksi (istilah Taiwan)"},{s:"视频",p:"shì pín",en:"video (mainland term)",id:"video (istilah daratan)"},{s:"垃圾",p:"lā jī",en:"garbage (mainland reading; Taiwan reads it lèsè)",id:"sampah (bacaan daratan; Taiwan membacanya lèsè)"},{s:"马铃薯",p:"mǎ líng shǔ",en:"potato (Taiwan term)",id:"kentang (istilah Taiwan)"}],tips:[{en:"Don't assume simplified characters or mainland vocabulary will read the same way in Taiwan, or vice versa.",id:"Jangan berasumsi aksara sederhana atau kosakata daratan akan dipahami sama di Taiwan, atau sebaliknya."},{en:"Avoid volunteering political opinions about cross-strait topics with new acquaintances.",id:"Hindari menyampaikan opini politik soal topik lintas-selat kepada kenalan baru."},{en:"In Taiwan, expect 計程車, 影片, and 馬鈴薯 instead of the mainland equivalents.",id:"Di Taiwan, siapkan diri menemui 計程車, 影片, dan 馬鈴薯, bukan padanan dari daratan."}]},{id:"university",icon:"",title:{en:"University communication",id:"Komunikasi di kampus"},body:{en:"Chinese academic culture is title-first: professors are addressed as Surname + 老师 (or 教授 for full professors), and your thesis supervisor is your 导师 (dǎoshī) — students often call them 老板 ('boss') informally among themselves, but never to their face. Messages to teachers open politely (老师您好) and close with 谢谢老师; blunt, subject-line-only messages read as rude.\n\nMost course logistics happen in WeChat groups rather than email. Reply promptly when named, keep group messages short, and take personal questions to private chat (私聊) instead of the group. When asking for help or a deadline extension, state the request briefly, apologize for the trouble (麻烦您了), and thank in advance — the polite frame matters more than a long justification.",id:"Budaya akademik Tiongkok mengutamakan gelar: dosen disapa Marga + 老师 (atau 教授 untuk profesor penuh), dan pembimbing skripsimu adalah 导师 (dǎoshī) — mahasiswa sering menyebutnya 老板 ('bos') secara informal sesama mereka, tapi tidak pernah di hadapannya. Pesan kepada dosen dibuka dengan sopan (老师您好) dan ditutup dengan 谢谢老师; pesan singkat tanpa salam terkesan kasar.\n\nSebagian besar urusan kuliah berlangsung di grup WeChat, bukan email. Balas segera bila disebut, tulis pesan grup dengan ringkas, dan bawa pertanyaan pribadi ke chat pribadi (私聊), bukan ke grup. Saat meminta bantuan atau perpanjangan tenggat, sampaikan permintaan secara singkat, minta maaf karena merepotkan (麻烦您了), dan ucapkan terima kasih di muka — bingkai yang sopan lebih penting daripada alasan yang panjang."},phrases:[{s:"老师您好",p:"lǎo shī nín hǎo",en:"hello, teacher (polite opener)",id:"halo, Pak/Bu (pembuka sopan)"},{s:"麻烦您了",p:"má fan nín le",en:"sorry to trouble you",id:"maaf merepotkan Anda"},{s:"导师",p:"dǎo shī",en:"thesis supervisor / advisor",id:"dosen pembimbing"},{s:"私聊",p:"sī liáo",en:"private chat (vs the group)",id:"chat pribadi (bukan di grup)"},{s:"谢谢老师",p:"xiè xie lǎo shī",en:"thank you, teacher (standard closer)",id:"terima kasih, Pak/Bu (penutup standar)"}],tips:[{en:"Open with 老师您好 and close with 谢谢老师 — the frame matters more than the length.",id:"Buka dengan 老师您好 dan tutup dengan 谢谢老师 — bingkainya lebih penting daripada panjangnya."},{en:"Course logistics live in WeChat groups; personal matters go to private chat.",id:"Urusan kuliah ada di grup WeChat; urusan pribadi lewat chat pribadi."}]},{id:"regional",icon:"",title:{en:"Regional vocabulary differences",id:"Perbedaan kosakata daerah"},body:{en:"Standard Mandarin is understood everywhere, but everyday words shift between regions. The north says 哪儿 (nǎr) with heavy erhua; the south prefers 哪里 (nǎlǐ) and drops the -r endings. A bicycle is 自行车 in the north and often 单车 in the south; tomato is 西红柿 in the north, 番茄 in the south; a potato can be 土豆, 马铃薯, or 洋芋 depending on where you are. Money is counted as 块 (kuài) in speech everywhere, while 元 (yuán) stays formal and written.\n\nNone of these are wrong anywhere — locals understand both — but noticing them explains why real speech differs from your textbook, and matching the local word makes you sound instantly more natural.",id:"Mandarin standar dipahami di mana-mana, tapi kata sehari-hari bergeser antar daerah. Utara memakai 哪儿 (nǎr) dengan erhua kental; selatan memilih 哪里 (nǎlǐ) dan menghilangkan akhiran -r. Sepeda adalah 自行车 di utara dan sering 单车 di selatan; tomat 西红柿 di utara, 番茄 di selatan; kentang bisa 土豆, 马铃薯, atau 洋芋 tergantung tempatnya. Uang dihitung 块 (kuài) dalam percakapan di mana pun, sedangkan 元 (yuán) tetap formal dan tulisan.\n\nTidak ada yang salah di mana pun — orang lokal paham keduanya — tapi menyadarinya menjelaskan kenapa percakapan asli berbeda dari buku teks, dan memakai kata setempat membuatmu langsung terdengar lebih alami."},phrases:[{s:"哪儿 / 哪里",p:"nǎr / nǎ lǐ",en:"where (north / south)",id:"di mana (utara / selatan)"},{s:"自行车 / 单车",p:"zì xíng chē / dān chē",en:"bicycle (north / south)",id:"sepeda (utara / selatan)"},{s:"西红柿 / 番茄",p:"xī hóng shì / fān qié",en:"tomato (north / south)",id:"tomat (utara / selatan)"},{s:"土豆 / 马铃薯",p:"tǔ dòu / mǎ líng shǔ",en:"potato (colloquial / formal)",id:"kentang (sehari-hari / formal)"},{s:"块 / 元",p:"kuài / yuán",en:"yuan (spoken / written)",id:"yuan (lisan / tulisan)"},{s:"打车 / 打的",p:"dǎ chē / dǎ dī",en:"to take a taxi (both common)",id:"naik taksi (keduanya umum)"}],tips:[{en:"Textbook words are never wrong — but echoing the local variant sounds natural fast.",id:"Kata buku teks tidak pernah salah — tapi meniru varian lokal cepat terdengar alami."}]},{id:"slang",icon:"",title:{en:"Internet slang (dates fast!)",id:"Bahasa gaul internet (cepat basi!)"},body:{en:"Chinese internet slang turns over fast — a term that was everywhere last year can mark you as out of touch this year. Treat every slang word as having a freshness date: understand them all, but deploy them sparingly and listen for what people around you actually still say.\n\nAs of 2026: 内卷 (involution / rat-race) and 躺平 (lying flat) have settled into normal vocabulary; 摆烂 (deliberately letting things rot) and 破防 (emotionally gotten-to) are still current; 666 (impressive) and 靠谱 (reliable) are long-stable; yyds ('eternal GOAT') and 绝绝子 peaked years ago and now read as dated; 佛系 (Buddha-like chill) is understood but no longer fresh. When in doubt, recognition is the goal — stale slang from a learner lands worse than no slang at all.",id:"Bahasa gaul internet Tiongkok berganti sangat cepat — istilah yang ada di mana-mana tahun lalu bisa membuatmu terkesan ketinggalan zaman tahun ini. Anggap setiap kata gaul punya tanggal kesegaran: pahami semuanya, tapi pakailah hemat dan dengarkan apa yang masih benar-benar dipakai orang di sekitarmu.\n\nPer 2026: 内卷 (persaingan berlebihan) dan 躺平 (rebahan / menyerah halus) sudah menjadi kosakata normal; 摆烂 (sengaja membiarkan hancur) dan 破防 (pertahanan emosi jebol) masih dipakai; 666 (keren) dan 靠谱 (bisa diandalkan) stabil sejak lama; yyds ('terbaik sepanjang masa') dan 绝绝子 sudah lewat masa jayanya dan kini terkesan basi; 佛系 (santai ala Buddha) dipahami tapi tidak segar lagi. Kalau ragu, cukup pahami saja — slang basi dari pemelajar terkesan lebih buruk daripada tanpa slang sama sekali."},phrases:[{s:"内卷",p:"nèi juǎn",en:"rat-race competition (stable since ~2020)",id:"persaingan berlebihan (stabil sejak ~2020)"},{s:"躺平",p:"tǎng píng",en:"to opt out / lie flat (stable)",id:"rebahan / menyerah halus (stabil)"},{s:"摆烂",p:"bǎi làn",en:"to stop trying on purpose (current)",id:"sengaja tak berusaha lagi (masih dipakai)"},{s:"破防",p:"pò fáng",en:"emotionally gotten-to (current)",id:"pertahanan emosi jebol (masih dipakai)"},{s:"666",p:"liù liù liù",en:"awesome, skilled (long-stable)",id:"keren, jago (stabil lama)"},{s:"yyds",p:"yǒng yuǎn de shén",en:"the GOAT (dated — peaked ~2021)",id:"terbaik sepanjang masa (basi — puncaknya ~2021)"}],tips:[{en:"Slang has a freshness date — recognition always helps, but using stale slang backfires.",id:"Bahasa gaul punya masa segar — memahami selalu berguna, tapi memakai yang basi jadi bumerang."},{en:"Copy the slang your actual chat partners use this month, not a list from last year.",id:"Tiru slang yang dipakai lawan bicaramu bulan ini, bukan daftar dari tahun lalu."}]},{id:"sensitive",icon:"",title:{en:"Words to be careful with",id:"Kata yang perlu hati-hati"},body:{en:"Some textbook-looking words carry baggage in real life. Calling a waitress 小姐 (xiǎojiě) alone can offend in mainland China because the word picked up a secondary meaning — use 服务员 (server) or the friendly 美女/帅哥 instead. 同志 (tóngzhì, 'comrade') survives in official contexts, but in everyday speech it now mostly means a gay person — don't use it as a general form of address. 农民 (farmer) is a neutral occupation word that also appears in put-downs — use it for occupations, never to describe someone's manners.\n\nDirectness about age, weight, and salary is more common in China than many learners expect, and elders may comment on yours warmly — but as an outsider, hold back from reciprocating until you can read the room. With any newly met group, food, family, and travel are reliably safe topics; politics is not a smalltalk category.",id:"Beberapa kata yang tampak baku di buku ternyata bermuatan dalam kehidupan nyata. Memanggil pelayan wanita hanya dengan 小姐 (xiǎojiě) bisa menyinggung di Tiongkok daratan karena kata itu mendapat makna sekunder — pakai 服务员 (pelayan) atau sapaan ramah 美女/帅哥. 同志 (tóngzhì, 'kamerad') masih hidup dalam konteks resmi, tapi dalam percakapan sehari-hari kini umumnya berarti orang gay — jangan dipakai sebagai sapaan umum. 农民 (petani) adalah kata pekerjaan netral yang juga muncul dalam ejekan — gunakan untuk pekerjaan, jangan untuk menilai perilaku orang.\n\nKeterusterangan soal umur, berat badan, dan gaji lebih umum di Tiongkok daripada dugaan banyak pemelajar, dan orang yang lebih tua mungkin mengomentarimu dengan hangat — tapi sebagai orang luar, tahan diri untuk membalas sampai kamu bisa membaca suasana. Dengan kelompok yang baru dikenal, makanan, keluarga, dan perjalanan adalah topik yang selalu aman; politik bukan kategori basa-basi."},phrases:[{s:"服务员",p:"fú wù yuán",en:"server (safe way to call staff)",id:"pelayan (sapaan aman untuk staf)"},{s:"美女 / 帅哥",p:"měi nǚ / shuài gē",en:"miss / young man (friendly service address)",id:"mbak / mas (sapaan ramah di toko)"},{s:"小姐姐 / 小哥哥",p:"xiǎo jiě jie / xiǎo gē ge",en:"young woman / young man (casual, safe)",id:"kakak perempuan / laki-laki (santai, aman)"},{s:"请问一下",p:"qǐng wèn yí xià",en:"excuse me (neutral attention-getter)",id:"permisi (cara netral menarik perhatian)"}],tips:[{en:"Address staff as 服务员 or 美女/帅哥 — never bare 小姐 in mainland China.",id:"Panggil staf dengan 服务员 atau 美女/帅哥 — jangan 小姐 saja di Tiongkok daratan."},{en:"Food, family, travel: safe smalltalk. Politics: not smalltalk.",id:"Makanan, keluarga, perjalanan: basa-basi aman. Politik: bukan basa-basi."}]},{id:"tea-water",icon:"🍵",title:{en:"Tea & hot water customs",id:"Kebiasaan teh & air panas"},body:{en:"Tea is the default hot drink offered to a guest almost immediately after they sit down, often before any real conversation starts. Declining is fine, but a cup will often be poured anyway as a matter of course — it's a gesture more than a genuine question.\n\nTopping off someone else's cup before your own — especially for someone senior to you — is a small, noticed courtesy called 添茶. A light tap of two fingers on the table when someone pours for you (叩指礼) is a silent thank-you that started in Cantonese custom and is now recognized much more broadly; it saves you from interrupting the conversation with a verbal thanks every time.\n\n热水 (hot water) is the everyday default far beyond just tea — restaurants commonly offer free hot water on request, many people carry a thermos to work, and asking for hot water instead of cold or iced drinks is completely normal, not just something reserved for when you're unwell. Older relatives may specifically recommend 多喝热水 ('drink more hot water') as general health advice, almost as a reflex, for everything from a cold to period pain to just feeling off.\n\nBeyond hot water, tea itself is a real category worth a little vocabulary — green, oolong, and pu'er are common everyday types, and a full gongfu tea ceremony (功夫茶) is a more deliberate, occasion-specific ritual rather than something expected at an ordinary meal.",id:"Teh adalah minuman hangat standar yang ditawarkan pada tamu hampir segera setelah mereka duduk, sering kali sebelum percakapan sungguhan dimulai. Menolak boleh saja, tapi secangkir teh biasanya tetap dituangkan sebagai kebiasaan — ini lebih merupakan gestur daripada pertanyaan sungguhan.\n\nMenuangkan teh untuk orang lain sebelum cangkirmu sendiri — terutama untuk orang yang lebih senior — adalah kesopanan kecil yang diperhatikan, disebut 添茶. Mengetuk ringan dua jari di meja saat seseorang menuangkan teh untukmu (叩指礼) adalah ucapan terima kasih tanpa kata yang berasal dari kebiasaan Kanton dan kini dikenal jauh lebih luas; ini membuatmu tidak perlu mengucapkan terima kasih secara lisan setiap kali.\n\n热水 (air panas) adalah kebiasaan sehari-hari yang jauh melampaui sekadar teh — restoran umumnya menyediakan air panas gratis kalau diminta, banyak orang membawa termos ke kantor, dan meminta air panas alih-alih air dingin atau es adalah hal yang benar-benar normal, bukan cuma untuk saat sedang tidak enak badan. Kerabat yang lebih tua mungkin secara khusus menyarankan 多喝热水 ('banyak minum air panas') sebagai nasihat kesehatan umum, hampir seperti refleks, untuk apa saja mulai dari masuk angin, nyeri haid, sampai sekadar merasa kurang enak badan.\n\nDi luar air panas, teh sendiri adalah kategori yang layak dipelajari sedikit kosakatanya — teh hijau, oolong, dan pu'er adalah jenis sehari-hari yang umum, dan upacara teh gongfu (功夫茶) yang lengkap adalah ritual yang lebih khusus untuk acara tertentu, bukan sesuatu yang diharapkan dalam makan biasa."},phrases:[{s:"请喝茶",p:"qǐng hē chá",en:"please, have some tea",id:"silakan minum teh"},{s:"我给您添茶",p:"wǒ gěi nín tiān chá",en:"let me top off your tea",id:"biar saya tambahkan tehnya"},{s:"谢谢，不用了",p:"xiè xie, bú yòng le",en:"thanks, that's alright (declining more)",id:"terima kasih, tidak usah"},{s:"麻烦给我一杯热水",p:"má fan gěi wǒ yì bēi rè shuǐ",en:"could I get a cup of hot water, please",id:"boleh minta segelas air panas"},{s:"多喝热水",p:"duō hē rè shuǐ",en:"drink more hot water (common well-wishing advice)",id:"banyak minum air panas (nasihat umum saat sakit)"},{s:"我不太能喝冰的",p:"wǒ bú tài néng hē bīng de",en:"I can't really drink cold drinks",id:"saya kurang cocok minum yang dingin"}],tips:[{en:"Expect tea to be offered and refilled without asking; a light finger-tap on the table says thanks without interrupting the conversation.",id:"Bersiaplah teh ditawarkan dan diisi ulang tanpa diminta; ketukan ringan jari di meja sudah cukup untuk berterima kasih tanpa memotong percakapan."},{en:"热水 is a real, common request, not just for when you're unwell — ask for it by name at restaurants and on trains.",id:"热水 adalah permintaan yang benar-benar umum, bukan hanya untuk saat sakit — mintalah langsung di restoran dan kereta."},{en:"Topping off others' cups before your own, especially seniors', is a small courtesy worth adopting.",id:"Menuangkan teh untuk orang lain sebelum cangkirmu sendiri, terutama untuk yang lebih senior, adalah kesopanan kecil yang layak dibiasakan."}]},{id:"chopsticks",icon:"🥢",title:{en:"Chopstick etiquette",id:"Etika sumpit"},body:{en:"Never leave chopsticks standing upright in a bowl of rice (插筷子) — it visually echoes incense sticks burning at a funeral altar, and it's one of the strongest table taboos in Chinese dining. Rest them flat across the top of the bowl, or on a chopstick rest (筷子架) if one is provided.\n\nA handful of smaller habits are worth knowing too: don't tap chopsticks against a bowl (敲碗), historically associated with beggars; don't point at people with them or spear food as if with a fork; and don't rummage through a shared dish hunting for the best piece — take from the section nearest you.\n\nAt shared, family-style meals, use serving chopsticks (公筷) for communal dishes if they're provided, or flip your own chopsticks to the clean end — a habit increasingly encouraged for hygiene. It's also common and appreciated to serve others, especially elders or guests, before serving yourself; placing a piece directly in someone's bowl is a small, normal gesture of hospitality, though it's fine to decline once if you'd rather serve yourself.\n\nResting your chopsticks parallel across your bowl between bites is a normal pause, not a sign you're finished; set them down neatly at the end of the meal, and avoid crossing them, which some consider a mild bad omen — a softer taboo than the funeral association, but easy to just avoid.",id:"Jangan pernah menancapkan sumpit tegak lurus di mangkuk nasi (插筷子) — bentuknya menyerupai dupa yang dibakar di altar pemakaman, dan ini adalah salah satu pantangan meja makan paling kuat dalam budaya makan Tionghoa. Letakkan sumpit mendatar di atas mangkuk, atau di sandaran sumpit (筷子架) kalau disediakan.\n\nBeberapa kebiasaan kecil lain juga penting diketahui: jangan mengetuk sumpit ke mangkuk (敲碗), yang secara historis dikaitkan dengan pengemis; jangan menunjuk orang dengan sumpit atau menusuk makanan seperti memakai garpu; dan jangan mengaduk-aduk hidangan bersama mencari potongan terbaik — ambil dari bagian yang terdekat denganmu.\n\nDalam makan bersama gaya keluarga, gunakan sumpit umum (公筷) untuk hidangan bersama kalau disediakan, atau balik sumpitmu sendiri ke ujung yang bersih — kebiasaan yang semakin dianjurkan demi kebersihan. Melayani orang lain, terutama yang lebih tua atau tamu, sebelum melayani diri sendiri juga umum dan dihargai; meletakkan sepotong makanan langsung di mangkuk seseorang adalah gestur keramahan kecil yang wajar, meski boleh saja menolak sekali kalau kamu lebih suka mengambil sendiri.\n\nMeletakkan sumpit sejajar di atas mangkuk di sela-sela makan adalah jeda biasa, bukan tanda sudah selesai; letakkan dengan rapi di akhir makan, dan hindari menyilangkannya, yang oleh sebagian orang dianggap sedikit sial — pantangan yang lebih ringan dibanding kaitan dengan pemakaman, tapi mudah saja untuk dihindari."},phrases:[{s:"公筷",p:"gōng kuài",en:"serving chopsticks (for shared dishes)",id:"sumpit umum (untuk hidangan bersama)"},{s:"我帮您夹一点",p:"wǒ bāng nín jiā yì diǎn",en:"let me serve you a bit",id:"biar saya ambilkan sedikit untuk Anda"},{s:"请把筷子放平",p:"qǐng bǎ kuài zi fàng píng",en:"please lay your chopsticks flat (gentle reminder)",id:"tolong sumpitnya diletakkan rata"},{s:"不用，谢谢",p:"bú yòng, xiè xie",en:"no need, thank you (declining being served)",id:"tidak usah, terima kasih"},{s:"筷子架",p:"kuài zi jià",en:"chopstick rest",id:"sandaran sumpit"},{s:"用公筷夹菜",p:"yòng gōng kuài jiā cài",en:"use the serving chopsticks to take food",id:"pakai sumpit umum untuk mengambil makanan"}],tips:[{en:"Never leave chopsticks standing upright in a rice bowl — it echoes funeral incense and is the single most important chopstick rule to know.",id:"Jangan pernah menancapkan sumpit tegak di mangkuk nasi — bentuknya menyerupai dupa pemakaman dan ini aturan sumpit paling penting yang perlu diketahui."},{en:"Use serving chopsticks (公筷) for shared dishes when they're provided, or flip your own to the clean end.",id:"Gunakan sumpit umum (公筷) untuk hidangan bersama kalau disediakan, atau balik sumpitmu sendiri ke ujung yang bersih."},{en:"Don't tap your bowl, point with chopsticks, or dig around a shared plate for the best piece.",id:"Jangan mengetuk mangkuk, menunjuk dengan sumpit, atau mengaduk-aduk hidangan bersama mencari potongan terbaik."}]},{id:"signs-notices",icon:"🪧",title:{en:"Reading real-world signs & notices",id:"Membaca papan tanda & pengumuman"},body:{en:"Public restrooms are marked 男 (men) and 女 (women), sometimes spelled out as 男厕/女厕; 洗手间 and 卫生间 are the general words for restroom you'll see on directional signs. 入口 and 出口 mark entrance and exit, 紧急出口 marks an emergency exit, and 电梯 (elevator) is distinct from 扶梯 (escalator).\n\nSafety and prohibition notices reuse a small, learnable set of patterns rather than needing separate vocabulary for every sign: 禁止 + [action] means 'forbidden to,' as in 禁止吸烟 (no smoking) or 禁止拍照 (no photography); 请勿 + [action] is the softer, more polite version, as in 请勿吸烟 or 请勿触摸 (please don't touch); and 小心 + [hazard] flags a hazard, as in 小心地滑 (caution, slippery floor) or 小心台阶 (mind the step).\n\nRetail and service notices are worth recognizing on sight: 谢绝参观 or 谢绝入内 (visitors not admitted), 内部人员 (staff only), 暂停营业 (temporarily closed) versus 正在营业 (open), and 免费 (free) versus 收费 (a fee applies). 扫码 ('scan the code') shows up constantly, from restaurant menus to payment counters.\n\nA few transit and street terms round this out: 站 (station/stop), 路 (road), 出站/进站 (exit/enter the station), and 单行道 (one-way street). Recognizing the recurring prefixes — 禁止/请勿/小心 — is usually more useful day to day than memorizing each individual sign.",id:"Toilet umum ditandai dengan 男 (pria) dan 女 (wanita), kadang dieja lengkap sebagai 男厕/女厕; 洗手间 dan 卫生间 adalah kata umum untuk toilet yang muncul di papan penunjuk arah. 入口 dan 出口 menandai pintu masuk dan keluar, 紧急出口 menandai pintu keluar darurat, dan 电梯 (lift) berbeda dari 扶梯 (eskalator).\n\nPengumuman keselamatan dan larangan memakai pola kecil yang bisa dipelajari dan dipakai ulang, bukan kosakata terpisah untuk setiap tanda: 禁止 + [tindakan] berarti 'dilarang,' seperti pada 禁止吸烟 (dilarang merokok) atau 禁止拍照 (dilarang memotret); 请勿 + [tindakan] adalah versi yang lebih halus dan sopan, seperti pada 请勿吸烟 atau 请勿触摸 (mohon jangan disentuh); dan 小心 + [bahaya] menandai bahaya, seperti pada 小心地滑 (hati-hati lantai licin) atau 小心台阶 (hati-hati anak tangga).\n\nPengumuman toko dan layanan juga penting dikenali sekilas: 谢绝参观 atau 谢绝入内 (pengunjung tidak diterima), 内部人员 (khusus karyawan), 暂停营业 (tutup sementara) lawan 正在营业 (sedang buka), serta 免费 (gratis) lawan 收费 (dikenakan biaya). 扫码 ('pindai kode') muncul di mana-mana, dari menu restoran sampai konter pembayaran.\n\nBeberapa istilah transportasi dan jalan juga melengkapi ini: 站 (stasiun/halte), 路 (jalan), 出站/进站 (keluar/masuk stasiun), dan 单行道 (jalan satu arah). Mengenali awalan yang berulang — 禁止/请勿/小心 — biasanya lebih berguna sehari-hari daripada menghafal setiap tanda satu per satu."},phrases:[{s:"禁止吸烟",p:"jìn zhǐ xī yān",en:"no smoking",id:"dilarang merokok"},{s:"请勿触摸",p:"qǐng wù chù mō",en:"please do not touch",id:"mohon jangan disentuh"},{s:"小心地滑",p:"xiǎo xīn dì huá",en:"caution, slippery floor",id:"hati-hati lantai licin"},{s:"男厕 / 女厕",p:"nán cè / nǚ cè",en:"men's / women's restroom",id:"toilet pria / wanita"},{s:"紧急出口",p:"jǐn jí chū kǒu",en:"emergency exit",id:"pintu keluar darurat"},{s:"内部人员",p:"nèi bù rén yuán",en:"staff only",id:"khusus karyawan"}],tips:[{en:"Learn 禁止/请勿 (forbidden/please don't) and 小心 (caution) as reusable prefixes — they recombine with almost any action or hazard.",id:"Pelajari 禁止/请勿 (dilarang/mohon jangan) dan 小心 (hati-hati) sebagai awalan yang bisa dipakai ulang — bisa digabung dengan hampir semua tindakan atau bahaya."},{en:"男/女 mark restrooms; 入口/出口 mark entrance/exit; 收费/免费 tell you whether something costs money.",id:"男/女 menandai toilet; 入口/出口 menandai pintu masuk/keluar; 收费/免费 memberi tahu apakah sesuatu berbayar."},{en:"Scanning a QR code (扫码) is now the default way to see a menu, pay, or check in almost everywhere.",id:"Memindai kode QR (扫码) kini menjadi cara standar untuk melihat menu, membayar, atau check-in hampir di mana saja."}]},{id:"service-interactions",icon:"🛎️",title:{en:"Common service interactions",id:"Interaksi layanan sehari-hari"},body:{en:"Ordering at a counter or restaurant usually starts with 我要… ('I'd like…') or the softer 麻烦你，我要… ('excuse me, I'd like…'). At a sit-down restaurant, calling out 服务员 ('waitstaff') or 麻烦一下 to get attention is completely normal and not considered rude, unlike in some dining cultures where it can feel abrupt.\n\nMobile payment by scanning a QR code (扫码支付, via Alipay or WeChat Pay) is the default almost everywhere, including small vendors and street food stalls; cash is still accepted in most places but functions as a genuine backup rather than the norm in most cities. 可以扫码吗? ('can I scan to pay?') or 可以用微信/支付宝吗? are natural questions if you're unsure.\n\nFor taxis and ride-hailing, hailing a cab on the street still works, but ride-hailing apps (滴滴, Didi) are more common in cities now. Drivers may ask 走高速吗? ('take the highway?') for a faster, tolled route versus a slower free one. Showing a pinned location on a map while saying 麻烦到这里 ('please, to here') is a reliable way to communicate a destination without needing perfect pronunciation.\n\nAt hotels and other counters, checking in as a foreign visitor usually requires your passport (护照), and 我有预订 ('I have a reservation') gets things moving quickly. Asking for the wifi password is extremely common — Wi-Fi密码是多少? A request softened with 麻烦你/麻烦您 tends to land better than a bare, direct ask in any of these settings.",id:"Memesan di konter atau restoran biasanya dimulai dengan 我要… ('saya mau…') atau versi yang lebih halus 麻烦你，我要… ('permisi, saya mau…'). Di restoran duduk, memanggil 服务员 ('pelayan') atau mengucapkan 麻烦一下 untuk menarik perhatian adalah hal yang benar-benar normal dan tidak dianggap tidak sopan, berbeda dengan sebagian budaya bersantap lain yang menganggapnya terlalu langsung.\n\nPembayaran seluler dengan memindai kode QR (扫码支付, lewat Alipay atau WeChat Pay) adalah cara standar hampir di mana saja, termasuk pedagang kecil dan kedai makanan kaki lima; uang tunai masih diterima di kebanyakan tempat tapi berfungsi sebagai cadangan yang sungguhan, bukan kebiasaan utama di kebanyakan kota. 可以扫码吗? ('boleh bayar dengan pindai kode?') atau 可以用微信/支付宝吗? adalah pertanyaan wajar kalau kamu ragu.\n\nUntuk taksi dan ojek daring, menyetop taksi di jalan masih berfungsi, tapi aplikasi pemesanan (滴滴, Didi) kini lebih umum di kota-kota. Sopir mungkin bertanya 走高速吗? ('lewat jalan tol?') untuk rute yang lebih cepat tapi berbayar dibanding rute gratis yang lebih lambat. Menunjukkan lokasi yang disematkan di peta sambil mengatakan 麻烦到这里 ('tolong ke sini') adalah cara yang bisa diandalkan untuk menyampaikan tujuan tanpa perlu pelafalan yang sempurna.\n\nDi hotel dan konter lain, check-in sebagai pengunjung asing biasanya memerlukan paspor (护照), dan 我有预订 ('saya sudah reservasi') membuat prosesnya berjalan cepat. Menanyakan kata sandi wifi adalah hal yang sangat umum — Wi-Fi密码是多少? Permintaan yang dilunakkan dengan 麻烦你/麻烦您 biasanya diterima lebih baik daripada permintaan langsung tanpa basa-basi di semua situasi ini."},phrases:[{s:"我要这个",p:"wǒ yào zhè ge",en:"I'd like this one",id:"saya mau yang ini"},{s:"麻烦一下",p:"má fan yí xià",en:"excuse me (getting attention politely)",id:"permisi (menarik perhatian dengan sopan)"},{s:"可以扫码支付吗",p:"kě yǐ sǎo mǎ zhī fù ma",en:"can I pay by scanning a code?",id:"boleh bayar dengan pindai kode?"},{s:"Wi-Fi密码是多少",p:"Wi-Fi mì mǎ shì duō shao",en:"what's the wifi password?",id:"berapa kata sandi wifi-nya?"},{s:"我有预订",p:"wǒ yǒu yù dìng",en:"I have a reservation",id:"saya sudah reservasi"},{s:"麻烦到这里",p:"má fan dào zhè lǐ",en:"please, to here (showing a location)",id:"tolong ke sini (sambil menunjukkan lokasi)"}],tips:[{en:"Calling out 服务员 or 麻烦一下 to get a server's attention is completely normal in China, not rude.",id:"Memanggil 服务员 atau mengucapkan 麻烦一下 untuk menarik perhatian pelayan adalah hal yang benar-benar normal di Tiongkok, bukan tidak sopan."},{en:"Mobile payment by QR code is the default nearly everywhere — carry a little cash as backup, not as your main plan.",id:"Pembayaran seluler lewat kode QR adalah standar hampir di mana saja — bawa sedikit uang tunai sebagai cadangan, bukan rencana utama."},{en:"A softening 麻烦你/麻烦您 before a request goes a long way in any service interaction.",id:"Kata pelunak 麻烦你/麻烦您 sebelum permintaan sangat membantu dalam interaksi layanan apa pun."}]},{id:"queuing",icon:"🚶",title:{en:"Queuing & public space",id:"Antre & ruang publik"},body:{en:"Formal queue lines — marked lanes at train stations, banks, and airports — are generally respected and enforced, especially in larger cities where queuing culture has strengthened noticeably over the past couple of decades through public campaigns. In less formally managed settings, like boarding a bus or squeezing into a crowded market stall, people commonly move up by proximity rather than strict arrival order, more so in some regions and among older crowds than others; if you notice this happening around you, moving forward calmly claims your spot rather than waiting to be invited.\n\nPersonal space in crowded public settings — subways, markets, sidewalks — tends to be smaller than many learners expect. Some jostling, close following, or squeezing past without an explicit 'excuse me' is normal and isn't meant as rude; a light 不好意思 still smooths things over if you're the one doing the moving.\n\nOn escalators, standing habits vary by city and have shifted over time — in some places standing on one side and walking on the other is common, in others people simply spread across both sides, especially when it's busy; watch what locals around you are doing rather than assuming one universal rule applies everywhere.\n\nOn public transit, offering your seat to elderly passengers, pregnant women, or parents with small children (让座) is a well-recognized courtesy, sometimes requested directly by a fellow passenger — 麻烦让一下座 — or simply gestured. Declining isn't inherently rude, but visibly ignoring a direct, polite request can draw quiet disapproval.",id:"Antrean resmi — jalur bertanda di stasiun kereta, bank, dan bandara — umumnya dihormati dan diberlakukan, terutama di kota-kota besar tempat budaya mengantre menguat cukup nyata dalam dua dekade terakhir lewat kampanye publik. Di suasana yang kurang terkelola secara formal, seperti naik bus atau berdesakan di kios pasar yang ramai, orang biasanya maju berdasarkan kedekatan posisi, bukan urutan kedatangan yang ketat, lebih terasa di sebagian daerah dan di antara kerumunan yang lebih tua dibanding yang lain; kalau kamu melihat ini terjadi di sekitarmu, maju dengan tenang justru mengamankan posisimu daripada menunggu dipersilakan.\n\nRuang pribadi di tempat umum yang ramai — kereta bawah tanah, pasar, trotoar — cenderung lebih sempit daripada yang diperkirakan banyak pemelajar. Sedikit desakan, mengikuti dari dekat, atau melewati seseorang tanpa 'permisi' yang eksplisit adalah hal normal dan bukan dimaksudkan sebagai tidak sopan; 不好意思 yang ringan tetap membantu melancarkan suasana kalau kamu yang sedang bergerak.\n\nDi eskalator, kebiasaan berdiri berbeda-beda antar kota dan berubah seiring waktu — di sebagian tempat berdiri di satu sisi dan berjalan di sisi lain adalah kebiasaan umum, di tempat lain orang menyebar di kedua sisi begitu saja, terutama saat ramai; perhatikan apa yang dilakukan orang lokal di sekitarmu daripada berasumsi ada satu aturan universal yang berlaku di mana-mana.\n\nDi transportasi umum, memberikan tempat duduk untuk penumpang lansia, ibu hamil, atau orang tua dengan anak kecil (让座) adalah kesopanan yang dikenal luas, kadang diminta langsung oleh penumpang lain — 麻烦让一下座 — atau cukup diisyaratkan. Menolak bukan berarti tidak sopan, tapi mengabaikan permintaan sopan yang langsung secara terang-terangan bisa memicu ketidaksukaan yang halus."},phrases:[{s:"排队",p:"pái duì",en:"to queue / line up",id:"mengantre"},{s:"麻烦让一下",p:"má fan ràng yí xià",en:"excuse me, could you make way?",id:"permisi, tolong beri jalan"},{s:"不好意思",p:"bù hǎo yì si",en:"excuse me (moving past someone)",id:"permisi (saat lewat/menyenggol)"},{s:"您先请",p:"nín xiān qǐng",en:"after you (offering priority)",id:"silakan duluan"},{s:"这是最后一个人吗",p:"zhè shì zuì hòu yí ge rén ma",en:"is this the end of the line?",id:"ini orang terakhir dalam antrean?"},{s:"给您让个座",p:"gěi nín ràng ge zuò",en:"let me give up my seat for you",id:"biar saya kasih tempat duduk untuk Anda"}],tips:[{en:"Formal lines at stations and airports are respected; looser settings may move by proximity rather than strict order — watch and match the room.",id:"Antrean resmi di stasiun dan bandara dihormati; suasana yang lebih longgar mungkin bergerak berdasarkan kedekatan posisi, bukan urutan ketat — amati dan sesuaikan."},{en:"A little jostling on crowded transit isn't rude; a light 不好意思 while moving through smooths it over.",id:"Sedikit desakan di transportasi yang ramai bukan tidak sopan; 不好意思 yang ringan saat lewat sudah cukup melancarkan suasana."},{en:"Offering your seat (让座) to elders, pregnant passengers, or parents with young kids is a well-recognized, appreciated courtesy.",id:"Memberikan tempat duduk (让座) untuk lansia, penumpang hamil, atau orang tua dengan anak kecil adalah kesopanan yang dikenal luas dan dihargai."}]},{id:"home-visits",icon:"🏠",title:{en:"Visiting someone's home",id:"Berkunjung ke rumah orang"},body:{en:"Bringing a small gift when visiting someone's home — fruit, snacks, tea, or something from your hometown — is standard practice, even for a casual visit. Showing up completely empty-handed to a first visit can feel a little bare, though close friends who visit often are usually more relaxed about it.\n\nRemoving your shoes at the door is common in most homes, and hosts often provide guest slippers (拖鞋). If you're unsure, glance at the entryway for a shoe rack, notice whether the host is in socks or slippers, or simply ask 要脱鞋吗? ('should I take off my shoes?').\n\nExpect to be offered food and drink almost immediately, along with a version of the same offering-and-declining ritual (推让) common at restaurants — an initial 'no thank you' is often just politeness, and a host who genuinely wants you to eat will keep offering. Complimenting the home, especially if the host has cooked, is normal, appreciated small talk.\n\nOverstaying is a minor concern in casual settings, but it's worth reading the room, since hosts may not tell you directly when it's time to go — a lull in conversation or dishes being cleared are more common cues than an explicit signal. Thanking the host warmly on the way out, with something like 今天真麻烦你了 ('sorry for all the trouble today'), closes the visit well.",id:"Membawa hadiah kecil saat berkunjung ke rumah seseorang — buah, camilan, teh, atau sesuatu dari kampung halamanmu — adalah kebiasaan standar, bahkan untuk kunjungan santai. Datang dengan tangan kosong sepenuhnya untuk kunjungan pertama bisa terasa agak kurang, meski sahabat dekat yang sering berkunjung biasanya lebih santai soal ini.\n\nMelepas sepatu di pintu masuk adalah kebiasaan umum di sebagian besar rumah, dan tuan rumah sering menyediakan sandal tamu (拖鞋). Kalau ragu, lihat apakah ada rak sepatu di pintu masuk, perhatikan apakah tuan rumah memakai kaus kaki atau sandal, atau cukup tanyakan 要脱鞋吗? ('apakah saya perlu lepas sepatu?').\n\nBersiaplah ditawari makanan dan minuman hampir seketika, disertai ritual menawarkan-dan-menolak (推让) yang sama seperti di restoran — penolakan pertama biasanya hanya basa-basi, dan tuan rumah yang sungguh-sungguh ingin kamu makan akan terus menawarkan. Memuji rumahnya, terutama kalau tuan rumah memasak sendiri, adalah basa-basi yang wajar dan dihargai.\n\nTerlalu lama berkunjung bukan masalah besar di suasana santai, tapi tetap perlu peka membaca situasi, karena tuan rumah mungkin tidak langsung memberi tahu kapan waktunya pulang — jeda dalam percakapan atau piring yang mulai dibereskan lebih sering menjadi isyarat daripada tanda yang eksplisit. Berterima kasih dengan hangat saat pamit, dengan ucapan seperti 今天真麻烦你了 ('hari ini benar-benar merepotkan Anda'), menutup kunjungan dengan baik."},phrases:[{s:"要脱鞋吗",p:"yào tuō xié ma",en:"should I take off my shoes?",id:"apakah saya perlu lepas sepatu?"},{s:"这是一点小礼物",p:"zhè shì yì diǎn xiǎo lǐ wù",en:"this is a small gift",id:"ini hadiah kecil"},{s:"您家真漂亮",p:"nín jiā zhēn piào liang",en:"your home is really lovely",id:"rumah Anda bagus sekali"},{s:"我吃饱了，谢谢",p:"wǒ chī bǎo le, xiè xie",en:"I'm full, thank you (declining more food)",id:"saya sudah kenyang, terima kasih"},{s:"今天真麻烦你了",p:"jīn tiān zhēn má fan nǐ le",en:"sorry for all the trouble today (closing thanks)",id:"hari ini benar-benar merepotkan Anda, terima kasih"},{s:"我该走了",p:"wǒ gāi zǒu le",en:"I should get going",id:"saya harus pamit sekarang"}],tips:[{en:"Bring a small gift when visiting someone's home, even casually — fruit, snacks, or tea are always safe.",id:"Bawa hadiah kecil saat berkunjung ke rumah orang, bahkan untuk kunjungan santai — buah, camilan, atau teh selalu aman."},{en:"Check for a shoe rack or ask 要脱鞋吗? — removing shoes at the door is common in most homes.",id:"Perhatikan rak sepatu atau tanyakan 要脱鞋吗? — melepas sepatu di pintu masuk adalah kebiasaan umum di sebagian besar rumah."},{en:"Expect to be offered food repeatedly; a genuine 'no' may need to be repeated more than once.",id:"Bersiaplah ditawari makanan berulang kali; penolakan yang sungguhan mungkin perlu diulang lebih dari sekali."}]},{id:"weddings-funerals",icon:"💐",title:{en:"Weddings & funerals: what to say",id:"Pernikahan & pemakaman: apa yang diucapkan"},body:{en:"At weddings, red is the traditional celebratory color, and guests commonly avoid wearing all-white or all-black, which can read as funeral colors. The standard gift is cash in a red envelope (红包), given in an auspicious, even amount that avoids the number 4 — common amounts often include a 6, 8, or 9, though the appropriate range varies a lot by region and how close you are to the couple, so asking a local friend what's typical is genuinely the safest approach. 新婚快乐 ('happy marriage') or 百年好合 ('may you stay together a hundred years') are common well-wishes to say directly to the couple.\n\nFunerals call for close to the opposite palette — white is the traditional mourning color, and mourners commonly wear white or muted, subdued colors rather than bright ones; red is avoided entirely in funeral contexts, including on cards or wrapping given around that time. Cash condolence gifts, when given, traditionally use odd amounts, the reverse convention from festive occasions, though practices vary by region and family. 节哀 ('please restrain your grief,' a standard, respectful condolence) is the safe, simple thing to say — an elaborate speech isn't expected or necessary.\n\nIf you're unsure what's expected as a guest at either event — dress code, gift amount, whether children are welcome — it's completely normal to ask a local friend or check the invitation itself rather than guess, since customs vary meaningfully by region, generation, and family tradition.",id:"Dalam pernikahan, merah adalah warna perayaan tradisional, dan tamu umumnya menghindari busana serba putih atau serba hitam, yang bisa terkesan seperti warna pemakaman. Hadiah standar adalah uang tunai dalam amplop merah (红包), diberikan dalam jumlah genap yang membawa keberuntungan dan menghindari angka 4 — jumlah yang umum sering mengandung angka 6, 8, atau 9, meski kisaran yang pas sangat bervariasi tergantung daerah dan seberapa dekat kamu dengan pasangan tersebut, jadi bertanya pada teman lokal tentang jumlah yang lazim benar-benar cara paling aman. 新婚快乐 ('selamat menempuh hidup baru') atau 百年好合 ('semoga langgeng selamanya') adalah ucapan selamat umum yang diucapkan langsung ke pasangan.\n\nPemakaman memakai palet yang hampir berkebalikan — putih adalah warna berkabung tradisional, dan pelayat umumnya memakai warna putih atau warna redup dan kalem, bukan warna cerah; merah sepenuhnya dihindari dalam konteks pemakaman, termasuk pada kartu atau bungkusan yang diberikan pada masa itu. Hadiah uang duka, kalau diberikan, secara tradisional memakai jumlah ganjil, kebalikan dari kebiasaan pada acara perayaan, meski praktiknya bervariasi menurut daerah dan keluarga. 节哀 ('mohon tabahkan diri,' ungkapan belasungkawa standar yang sopan) adalah hal yang aman dan sederhana untuk diucapkan — pidato yang panjang tidak diharapkan atau diperlukan.\n\nKalau kamu ragu apa yang diharapkan sebagai tamu di salah satu acara ini — kode busana, jumlah hadiah, apakah anak-anak boleh diajak — sangat wajar untuk bertanya pada teman lokal atau memeriksa undangannya langsung daripada menebak-nebak, karena kebiasaannya benar-benar berbeda menurut daerah, generasi, dan tradisi keluarga."},phrases:[{s:"新婚快乐",p:"xīn hūn kuài lè",en:"congratulations on your marriage",id:"selamat menempuh hidup baru"},{s:"百年好合",p:"bǎi nián hǎo hé",en:"may you stay together a hundred years",id:"semoga langgeng selamanya"},{s:"节哀",p:"jié āi",en:"please accept my condolences (standard phrase)",id:"turut berduka cita (ungkapan standar)"},{s:"请节哀顺变",p:"qǐng jié āi shùn biàn",en:"please take care of yourself in this difficult time",id:"semoga Anda tabah menghadapinya"},{s:"红包",p:"hóng bāo",en:"red envelope (cash gift)",id:"amplop merah (hadiah uang)"},{s:"恭喜恭喜",p:"gōng xǐ gōng xǐ",en:"congratulations! (general, festive)",id:"selamat, selamat!"}],tips:[{en:"Avoid all-white or all-black at a wedding, and avoid red entirely at a funeral — the color conventions are close to opposite.",id:"Hindari busana serba putih atau serba hitam di pernikahan, dan hindari warna merah sepenuhnya di pemakaman — kebiasaan warnanya hampir berkebalikan."},{en:"Wedding cash gifts are usually an even, auspicious amount (avoiding 4); condolence gifts traditionally use odd amounts — but ask a local friend, since customs vary by region.",id:"Hadiah uang pernikahan biasanya berjumlah genap dan membawa keberuntungan (hindari angka 4); hadiah duka secara tradisional berjumlah ganjil — tapi tanyakan pada teman lokal, karena kebiasaannya berbeda tiap daerah."},{en:"节哀 is the simple, respectful thing to say at a funeral; an elaborate speech isn't expected.",id:"节哀 adalah ucapan sederhana dan sopan untuk pemakaman; pidato panjang tidak diharapkan."}]},{id:"dialects",icon:"🗣️",title:{en:"Standard Mandarin vs local dialects",id:"Mandarin baku vs dialek lokal"},body:{en:"Standard Mandarin (普通话, Pǔtōnghuà) is taught in schools nationwide and is spoken by nearly everyone under middle age, but it coexists with dozens of genuinely distinct regional languages, or topolects — Cantonese (粤语) in Guangdong and Hong Kong, Shanghainese (上海话) and other Wu varieties around Shanghai, Hokkien/Min (闽南话) in Fujian and Taiwan, Sichuanese (四川话), and many more — several of which aren't mutually intelligible with Mandarin at all, despite sharing a writing system.\n\nIn many homes and among older generations especially, the local dialect is still the language of daily life, with Mandarin reserved for school, work, media, and talking to outsiders. Younger, urban speakers are often fully bilingual in Mandarin and their local dialect, switching between them depending on who they're talking to. In a handful of cities — Shanghai and Guangzhou/Hong Kong are the clearest examples — the local language carries real local pride and identity, and even a few words of it can land well from a learner who otherwise only speaks Mandarin.\n\nAs a learner, you'll almost always be addressed in Mandarin, and Mandarin gets you everywhere in the country — this isn't a barrier you need to solve. It does explain a few things you might notice along the way: an older relative or shopkeeper who seems to speak Mandarin with an unusual accent, or Mandarin peppered with dialect words in casual conversation, especially in the south.",id:"Bahasa Mandarin baku (普通话, Pǔtōnghuà) diajarkan di sekolah-sekolah di seluruh negeri dan dituturkan oleh hampir semua orang di bawah usia paruh baya, tapi bahasa ini hidup berdampingan dengan puluhan bahasa daerah yang benar-benar berbeda — bahasa Kanton (粤语) di Guangdong dan Hong Kong, bahasa Shanghai (上海话) dan varian Wu lainnya di sekitar Shanghai, Hokkien/Min (闽南话) di Fujian dan Taiwan, bahasa Sichuan (四川话), dan masih banyak lagi — beberapa di antaranya sama sekali tidak bisa saling dipahami dengan bahasa Mandarin, meski berbagi sistem tulisan yang sama.\n\nDi banyak rumah tangga dan terutama di kalangan generasi yang lebih tua, dialek lokal masih menjadi bahasa sehari-hari, sementara bahasa Mandarin disediakan untuk sekolah, kerja, media, dan berbicara dengan orang luar. Penutur muda perkotaan sering kali sepenuhnya dwibahasa dalam Mandarin dan dialek lokalnya, berpindah-pindah tergantung lawan bicaranya. Di beberapa kota — Shanghai dan Guangzhou/Hong Kong adalah contoh paling jelas — bahasa lokal membawa kebanggaan dan identitas daerah yang sungguhan, dan bahkan beberapa patah kata darinya bisa diterima dengan baik dari pemelajar yang sebenarnya hanya bisa bahasa Mandarin.\n\nSebagai pemelajar, kamu hampir selalu akan disapa dalam bahasa Mandarin, dan bahasa Mandarin membawamu ke mana saja di negara ini — ini bukan hambatan yang perlu kamu atasi. Tapi ini menjelaskan beberapa hal yang mungkin kamu perhatikan di sepanjang jalan: kerabat yang lebih tua atau pemilik toko yang tampak berbicara Mandarin dengan aksen yang tidak biasa, atau bahasa Mandarin yang bercampur kata-kata dialek dalam percakapan santai, terutama di selatan."},phrases:[{s:"普通话",p:"pǔ tōng huà",en:"Standard Mandarin (the national standard)",id:"bahasa Mandarin baku (standar nasional)"},{s:"方言",p:"fāng yán",en:"regional dialect / topolect",id:"dialek daerah"},{s:"你会说方言吗",p:"nǐ huì shuō fāng yán ma",en:"do you speak the local dialect?",id:"apakah Anda bisa bahasa daerah setempat?"},{s:"我只会说普通话",p:"wǒ zhǐ huì shuō pǔ tōng huà",en:"I can only speak Standard Mandarin",id:"saya hanya bisa bahasa Mandarin baku"},{s:"粤语",p:"yuè yǔ",en:"Cantonese",id:"bahasa Kanton"},{s:"上海话",p:"shàng hǎi huà",en:"Shanghainese",id:"bahasa Shanghai"}],tips:[{en:"Standard Mandarin works everywhere in China — you never need local dialect to get by as a learner.",id:"Bahasa Mandarin baku berlaku di mana saja di Tiongkok — kamu tidak pernah perlu dialek lokal untuk bisa berkomunikasi sebagai pemelajar."},{en:"Some regional languages (Cantonese, Shanghainese, Hokkien, and others) aren't mutually intelligible with Mandarin, despite sharing characters in writing.",id:"Sebagian bahasa daerah (Kanton, Shanghai, Hokkien, dan lainnya) tidak bisa saling dipahami dengan bahasa Mandarin, meski berbagi aksara yang sama dalam tulisan."},{en:"Hearing dialect words mixed into Mandarin, or an unusual accent from an older speaker, is completely normal, especially in the south.",id:"Mendengar kata-kata dialek yang tercampur dalam bahasa Mandarin, atau aksen yang tidak biasa dari penutur yang lebih tua, adalah hal yang sepenuhnya normal, terutama di selatan."}]}],e={addressing:"family",refusals:"etiquette",disagreement:"etiquette",compliments:"etiquette",apologies:"etiquette",restaurant:"food",gifts:"etiquette",wechat:"etiquette","business-cards":"work",workplace:"work","family-terms":"family",names:"family",holidays:"festivals",numbers:"festivals",face:"etiquette","taiwan-mainland":"etiquette",university:"work",regional:"etiquette",slang:"etiquette",sensitive:"etiquette","tea-water":"food",chopsticks:"food","signs-notices":"etiquette","service-interactions":"etiquette",queuing:"etiquette","home-visits":"etiquette","weddings-funerals":"festivals",dialects:"etiquette"};a.s(["CULTURE",0,n,"CULTURE_CATEGORIES",0,[{id:"etiquette",label:{en:"Everyday etiquette",id:"Etika sehari-hari"}},{id:"food",label:{en:"Food & drink",id:"Makanan & minuman"}},{id:"family",label:{en:"Family & address",id:"Keluarga & sapaan"}},{id:"work",label:{en:"Work & study",id:"Kerja & studi"}},{id:"festivals",label:{en:"Festivals & beliefs",id:"Hari raya & kepercayaan"}}],"categoryForTopic",0,a=>e[a]??"etiquette","cultureById",0,a=>n.find(n=>n.id===a)],61627);let i="mai.culture.v1";function t(){try{return JSON.parse(localStorage.getItem(i)??"{}")}catch{return{}}}a.s(["getCultureProgress",0,t,"isCultureRead",0,function(a){return a in t()},"markCultureRead",0,function(a){let n=t();n[a]=Date.now(),localStorage.setItem(i,JSON.stringify(n))}],35045)}]);